TTS_VOICES = ("hu-HU-NoemiNeural", "hu-HU-TamasNeural")
VOICES_OK = ("browser",) + TTS_VOICES + tuple("srv:" + v for v in TTS_VOICES)
_VOICE_RE = re.compile(r"^[a-z]{2,3}-[A-Z]{2}-[A-Za-z]+Neural$")


def tts_voice(v):
    """Ervenyes edge-tts hangnev (a magyarokon kivul a tobbnyelvu hangok is), kulonben az alapertelmezett."""
    return v if (v in TTS_VOICES or (isinstance(v, str) and _VOICE_RE.match(v))) else TTS_VOICES[0]


def voice_ok(v):
    if v == "browser":
        return True
    if isinstance(v, str) and v.startswith("srv:"):
        v = v[4:]
    return isinstance(v, str) and tts_voice(v) == v
