def dlog(msg):
    """Rovid, idobelyeges hibanaplo (airoguide_debug.log, ~600 KB-nal forog), hogy elakadas / hiba utolag kideritheto legyen."""
    try:
        if os.path.exists(DBG_FILE) and os.path.getsize(DBG_FILE) > 600000:
            os.replace(DBG_FILE, DBG_FILE + ".old")
        with open(DBG_FILE, "a", encoding="utf-8") as f:
            f.write(time.strftime("%Y-%m-%d %H:%M:%S ") + str(msg) + "\n")
    except Exception:
        pass
