SIGHT_RE = re.compile(
    "(?:" + "|".join(re.escape(w) for w in SIGHT_WORDS_ANYWHERE) + ")\\w*"
    + "|\\b(?:" + "|".join(re.escape(w) for w in SIGHT_WORDS_WHOLE) + ")\\b",
    re.I)


def is_sight(desc, cats):
    text = (desc or "") + " | " + " | ".join(cats)
    return bool(SIGHT_RE.search(text))


