def dlang():
    c = S.get("dlang") or S.get("lang") or "hu"
    return c if c in LANGS else "hu"


def vlang():
    c = S.get("vlang") or S.get("lang") or "hu"
    return c if c in LANGS else "hu"


def desc_foreign():
    return dlang() != "hu"



def load_settings():
    try:
        with open(SETTINGS_FILE, "r", encoding="utf-8") as f:
            d = json.load(f)
        with lock:
            for k in PERSIST:
                if k in d and type(d[k]) == type(S[k]):
                    S[k] = d[k]
            if "tutorial_seen" not in d and d.get("welcome_seen"):    # a mar hasznalo felhasznalonak nem indul el automatikusan
                S["tutorial_seen"] = True
            if "lang_set" not in d and d.get("welcome_seen"):      # a mar hasznalo felhasznalonak nem kerul elo az elso inditasi nyelvvalaszto
                S["lang_set"] = True
            if d.get("cfg_ver", 0) < 3:          # regebbi beallitasok: a szovegek keszuljenek az egesz utvonalra, nagyobb napi korlattal
                S["text_ahead"] = 5000
                S["ai_daily_max"] = max(S["ai_daily_max"], 100)
                S["cfg_ver"] = 3
            if d.get("cfg_ver", 0) < 4:          # egyszerusitett folyamat: a leirasok tavolsag szerint, sorban keszulnek
                S["text_mode"] = "auto"
                S["pipeline"] = "simple"
                S["cfg_ver"] = 4
            if d.get("cfg_ver", 0) < 6:          # a csillag-szuro a kliensben van; a nem-latnivalo cikkeket (szemelyek, fogalmak) viszont a szerver szuri
                S["min_tier"] = 0
                S["sights_only"] = True
                S["cfg_ver"] = 6
            if d.get("cfg_ver", 0) < 7:          # a bevalt gyors modell az alap (a "latest" alias lassu/terhelt tud lenni)
                if S.get("gemini_model") in ("", "gemini-3.5-flash-lite", None) or "latest" in str(S.get("gemini_model")):
                    S["gemini_model"] = "gemini-3.5-flash-lite"
                S["cfg_ver"] = 7
            if d.get("ver") != 2:
                S["source"] = "idx"          # uj alapforras a regi beallitasok helyett
            if S["voice"] != "" and not voice_ok(S["voice"]):
                S["voice"] = ""
    except Exception:
        pass


