# ---------------------------------------------------------------- geometria
def hav_km(lat1, lon1, lat2, lon2):
    r = 6371.0088
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dp, dl = p2 - p1, math.radians(lon2 - lon1)
    a = math.sin(dp / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dl / 2) ** 2
    return 2 * r * math.asin(math.sqrt(a))


def bearing(lat1, lon1, lat2, lon2):
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dl = math.radians(lon2 - lon1)
    y = math.sin(dl) * math.cos(p2)
    x = math.cos(p1) * math.sin(p2) - math.sin(p1) * math.cos(p2) * math.cos(dl)
    return (math.degrees(math.atan2(y, x)) + 360) % 360


def side_of(rel):
    if S.get("lang", "hu") != "hu":
        return "ahead" if abs(rel) <= 35 else ("right" if 35 < rel <= 145 else ("left" if -145 <= rel < -35 else "behind you"))
    if abs(rel) <= 35:
        return "elöl"
    if 35 < rel <= 145:
        return "jobbra"
    if -145 <= rel < -35:
        return "balra"
    return "mögötted"


def sector8(rel):
    a = abs(rel)
    if S.get("lang", "hu") != "hu":
        if a <= 22.5:
            return "ahead"
        if a >= 157.5:
            return "behind"
        sd = "right" if rel > 0 else "left"
        return ("ahead " + sd) if a < 67.5 else (sd if a <= 112.5 else ("behind " + sd))
    if a <= 22.5:
        return "elöl"
    if a >= 157.5:
        return "hátul"
    side = "jobbra" if rel > 0 else "balra"
    if a < 67.5:
        return side + " elöl"
    if a <= 112.5:
        return side
    return side + " hátul"


def eta_sec(gs_kt, ahead_km):
    """Becsult erkezesi ido masodpercben (a legkozelebbi pontig), vagy None ha nem ertelmezheto."""
    if gs_kt is None or gs_kt < 15 or ahead_km is None or ahead_km < 0:
        return None
    return int(round(ahead_km / (gs_kt * 1.852 / 3600.0)))


# ---------------------------------------------------------------- Wikipedia
_rl_lock = threading.Lock()
_next_ok = [0.0]


def wiki_get(params, api=None, fv2=True):
    q = dict(params)
    q["format"] = "json"
    if fv2:
        q["formatversion"] = "2"
    url = (api or WIKI_API) + "?" + urllib.parse.urlencode(q)
    last_err = None
    for attempt in range(5):
        with _rl_lock:                       # a kerések között legalább MIN_INTERVAL telik el
            wait = _next_ok[0] - time.time()
            if wait > 0:
                time.sleep(wait)
            _next_ok[0] = time.time() + WSTAT["iv"]       # alkalmazkodó kérésköz: hibánál lassul, sikernél gyorsul
        WSTAT["req"] += 1
        try:
            req = urllib.request.Request(url, headers={"User-Agent": UA, "Accept-Encoding": "identity"})
            with _one_at_a_time:
                with urllib.request.urlopen(req, timeout=20) as r:
                    out = json.loads(r.read().decode("utf-8"))
            WSTAT["iv"] = max(MIN_INTERVAL, WSTAT["iv"] * 0.97)
            return out
        except urllib.error.HTTPError as e:
            last_err = e
            WSTAT["code"] = e.code
            if e.code in (429, 503) and attempt < 4:
                WSTAT["iv"] = min(3.0, WSTAT["iv"] * 1.7)
                ra = e.headers.get("Retry-After") if e.headers else None
                delay = float(ra) if ra and ra.strip().isdigit() else RETRY_BASE * (2 ** attempt)
                delay = min(delay, 10.0)
                with _rl_lock:
                    _next_ok[0] = max(_next_ok[0], time.time() + delay)
                WSTAT["retry"] += 1
                WSTAT["slow"] += delay
                continue
            raise
    raise last_err


def wiki_query_all(params, api=None):
    pages = {}
    cont = {}
    for _ in range(12):
        r = wiki_get(dict(params, **cont), api=api)
        for p in r.get("query", {}).get("pages", []):
            d = pages.setdefault(p.get("pageid"), {})
            for k, v in p.items():
                if k == "categories":
                    d.setdefault("categories", []).extend(v)
                else:
                    d[k] = v
        if "continue" in r:
            cont = r["continue"]
        else:
            break
    return pages


# --- keresesi geometria: tobb kisebb kor lefedi a teruletet, mert egy keresesre
# --- a Wikipedia legfeljebb 500 talalatot ad (tavolsag szerint a legkozelebbieket)
GEO_R = 5.0        # km: egy keresokor sugara
GEO_STEP = 8.0     # km: a korok kozeppontjainak racsa
MAX_CAND = 3000    # ennyi jeloltet vizsgalunk legfeljebb
MIN_GEO_R = 0.35   # km: ennel kisebb korre mar nem bontjuk tovabb
MAX_GEO_CALLS = 160  # egy keresesnel legfeljebb ennyi Wikipedia-geosearch hivas
LIGHT_EN = {}      # angol Wikipedia: oldalazonosito -> mint a LIGHT
FULL_EN = {}       # angol szoveg + kep
SLH = {}           # wikidata-azonosito -> magyar cikk cime ("" = nincs)
VIS = {}           # "hogyan ismered fel a levegobol": kulcs ("hu:<id>" / "en:<id>" / "ai:...") -> szoveg (ures is lehet)
FAILN = {}          # fordítasi kudarcok szama helyenkent
AIC = {}           # AI-javaslatok szakaszonkent: sig -> [javaslatok]
TR = {}            # fordito-gyorsitotar: "en:<id>" -> {title, kind, text}
SLC = {}           # wikidata-azonosito -> nyelvi valtozatok szama (jelentoseg-jelzo)
LIGHT = {}         # pageid -> {title, desc, skip, sight, len, qid, tw}   (nem valtozik, gyorsitotar)
FULL = {}          # pageid -> {extract, thumb}
SCAN_INFO = {"circles": 0, "cand": 0, "capped": False, "src": ""}
CACHE_FILE = os.path.join(APP_DIR, "airoguide_cache.json")


_MAPIMG_RE = re.compile(r"(?<![a-z])map(?![a-z])|t[eé]rk[eé]p|karte|locator|location|helyzet|pozíci|pozici", re.I)


def bad_thumb(u):
    """A cikk 'vezerkepe' neha terkep (elhelyezkedes-terkep), nem a helyrol keszult fenykep: az ilyet nem hasznaljuk."""
    try:
        fn = urllib.parse.unquote((u or "").rsplit("/", 1)[-1])
    except Exception:
        return False
    return bool(u) and bool(_MAPIMG_RE.search(fn))


def good_thumb(p):
    u = (p.get("thumbnail") or {}).get("source", "")
    return "" if bad_thumb(u) else u


def load_cache():
    try:
        with open(CACHE_FILE, "r", encoding="utf-8") as f:
            d = json.load(f)
        for k, v in d.get("light", {}).items():
            if not v.get("title") and not v.get("miss"):      # egy korabbi hibas/hianyos valasz miatt ures rekord: ujra le kell kerni
                continue
            LIGHT[int(k)] = v
        for k, v in d.get("full", {}).items():
            FULL[int(k)] = v
        WD.update(d.get("wd", {}))
        LL.update(d.get("ll", {}))
        HUP.update(d.get("hup", {}))
        AIC.update(d.get("ai", {}))
        VIS.update(d.get("vis", {}))
        WDT.update(d.get("wdt", {}))
        HUT.update(d.get("hut", {}))
        ENT.update(d.get("ent", {}))
        OVR.update(d.get("ovr", {}))
        LISTC.update(d.get("lc", {}))
        SLC.update(d.get("sl", {}))
        SLH.update(d.get("slh", {}))
        TR.update(d.get("tr", {}))
        for k, v in d.get("len", {}).items():
            LIGHT_EN[int(k)] = v
        for k, v in d.get("fen", {}).items():
            FULL_EN[int(k)] = v
        for dd_ in (FULL, FULL_EN, HUP, OVR):                   # a korabban elmentett terkep-kepek is kiesnek
            for v_ in dd_.values():
                if isinstance(v_, dict) and bad_thumb(v_.get("thumb")):
                    v_["thumb"] = ""
    except Exception:
        pass


def apply_ovr(pois):
    # a kerésre / sorban elkészült leírások (OVR) visszaírása a listába: újraindítás és frissítés után is megmaradnak
    try:
        for p in pois or []:
            ov = OVR.get(str(p.get("id"))) or OVR.get(p.get("id"))
            if ov:
                p.update(ov)
    except Exception:
        pass
    return pois


def save_cache():
    # tobb szal ir a szotarakba, ezert menteskor "dictionary changed size" hiba johet: ilyenkor ujraprobaljuk, hogy a leirasok ne vesszenek el
    for _try in range(6):
        try:
            tmp = CACHE_FILE + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump({"light": dict(LIGHT), "full": dict(FULL), "wd": dict(WD), "ll": dict(LL), "hup": dict(HUP), "sl": dict(SLC), "slh": dict(SLH), "tr": dict(TR), "len": dict(LIGHT_EN), "fen": dict(FULL_EN), "ai": dict(AIC), "vis": dict(VIS), "wdt": dict(WDT), "hut": dict(HUT), "ent": dict(ENT), "ovr": dict(OVR), "lc": dict(LISTC)}, f, ensure_ascii=False)
            os.replace(tmp, CACHE_FILE)
            return
        except RuntimeError:
            time.sleep(0.05 * (_try + 1))
        except Exception:
            return


def polar(lat, lon, hdg, plat, plon):
    d = hav_km(lat, lon, plat, plon)
    rel = 0.0
    if hdg is not None:
        rel = ((bearing(lat, lon, plat, plon) - hdg + 540) % 360) - 180
    return d, rel


def offset(lat, lon, dx_km, dy_km):
    return (lat + dy_km / 111.32,
            lon + dx_km / (111.32 * max(0.05, math.cos(math.radians(lat)))))


def circle_ok(lat, lon, hdg, cone_half, radius_km, c, rr):
    d, rel = polar(lat, lon, hdg, c[0], c[1])
    if d > radius_km + rr:
        return False
    if cone_half is not None and d > rr:
        spread = math.degrees(math.asin(min(1.0, rr / d)))
        if abs(rel) > cone_half + spread:
            return False
    return True


def geo_circles(lat, lon, hdg, cone_half, radius_km):
    pts = []
    n = int(math.ceil((radius_km + GEO_R) / GEO_STEP)) + 1
    for j in range(-n, n + 1):
        for i in range(-n, n + 1):
            dx = i * GEO_STEP + (GEO_STEP / 2 if j % 2 else 0)
            dy = j * GEO_STEP * 0.866
            c = offset(lat, lon, dx, dy)
            if circle_ok(lat, lon, hdg, cone_half, radius_km, c, GEO_R):
                pts.append(c)
    return pts


TYPE_STRONG = re.compile(r"vár|kastély|palota|székesegyház|katedrális|bazilika|templom|kolostor|apátság|zsinagóga|mecset|múzeum|"
                         r"emlékmű|erőd|vízesés|kilátó|torony|híd|amfiteátrum|romváros|régészeti|világörökség|nemzeti park|"
                         r"állatkert|fürdő|csúcs|szurdok|sziget|vasút|városháza|színház|opera|stadion|repülőtér|fjord|gleccser|vulkán|kráter|kanyon|gejzír|öböl|félsziget|szoros|sivatag", re.I)
TYPE_MEDIUM = re.compile(r"park|szobor|emlékhely|tér\b|kút|temető|sírkert|villa|kúria|malom|major|skanzen|erdő|forrás|kert|barlang|hegy|tó\b", re.I)
TRIVIAL = re.compile(r"üreg|zsomboly|víznyelő|hasadék|\d+\.\s*sz\.|kereszt|emlékkő|kopjafa|megállóhely|vasútállomás|buszmegálló|"
                     r"lakótelep|bérház|családi ház|iskola|óvoda|sportpálya|benzinkút|szálloda|panzió|étterem", re.I)


def type_weight(desc, cats, title=""):
    txt = (desc or "") + " | " + " | ".join(cats or [])
    w = 0.0
    if TYPE_STRONG.search(desc or ""):
        w += 1.5
    elif TYPE_MEDIUM.search(desc or ""):
        w += 0.5
    elif TYPE_STRONG.search(txt):
        w += 0.5
    if re.search(r"világörökség", txt, re.I):
        w += 3.0
    if re.search(r"műemlék|védett|nemzeti park|tájvédelmi|természetvédelmi", txt, re.I):
        w += 0.7
    if TRIVIAL.search((title or "") + " " + (desc or "")):
        w -= 2.5
    return w


def light_info(ids):
    need = [i for i in ids if i not in LIGHT or LIGHT[i].get("v") != 3]
    chunks = [need[k:k + 50] for k in range(0, len(need), 50)]

    def work(ch):
        return wiki_query_all({
            "action": "query", "pageids": "|".join(str(x) for x in ch),
            "prop": "description|categories|info|pageprops", "ppprop": "wikibase_item",
            "cllimit": "max", "clshow": "!hidden",
        })

    with ThreadPoolExecutor(max_workers=2) as ex:
        for ch, info in zip(chunks, ex.map(work, chunks)):
            for pid in ch:
                p = info.get(pid, {})
                desc = (p.get("description") or "").strip()
                cats = [c.get("title", "").replace("Kategória:", "") for c in p.get("categories", [])]
                LIGHT[pid] = {"title": p.get("title", ""), "desc": desc, "skip": bool(SKIP_DESC.match(desc)),
                              "sight": is_sight(desc, cats),
                              "len": int(p.get("length") or 0),
                              "qid": (p.get("pageprops") or {}).get("wikibase_item", ""),
                              "tw": type_weight(desc, cats, p.get("title", "")), "v": 3}


_last_save = [time.time()]


def lite_info(ids):
    """Gyors elso kor: leiras, cikkhossz, wikidata-azonosito (kategoriak nelkul; az sokkal lassabb)."""
    need = [i for i in ids if LIGHT.get(i, {}).get("v") not in (3, 4)]
    chunks = [need[k:k + 50] for k in range(0, len(need), 50)]

    def work(ch):
        return wiki_get({"action": "query", "pageids": "|".join(str(x) for x in ch),
                         "prop": "description|info|pageprops", "ppprop": "wikibase_item"})

    with ThreadPoolExecutor(max_workers=2) as ex:
        for ch, r in zip(chunks, ex.map(work, chunks)):
            pages = {p.get("pageid"): p for p in r.get("query", {}).get("pages", [])}
            for pid in ch:
                p = pages.get(pid, {})
                desc = (p.get("description") or "").strip()
                title = p.get("title", "") if not p.get("missing") else ""
                LIGHT[pid] = {"title": title, "desc": desc, "skip": bool(SKIP_DESC.match(desc)),
                              "sight": bool(SIGHT_RE.search(desc)),
                              "len": int(p.get("length") or 0),
                              "qid": (p.get("pageprops") or {}).get("wikibase_item", ""),
                              "tw": type_weight(desc, [], title), "v": 4 if p else 0, "cats": 0}
                if p.get("missing"):
                    LIGHT[pid]["miss"] = True
            if time.time() - _last_save[0] > 20:          # megszakadt/újraindított futásnál se vesszen el a lekért adat
                _last_save[0] = time.time()
                save_cache()


def cats_info(ids):
    """Kategoriak csak azoknak, akik a leirasuk alapjan nem latnivalok, de nem is jelentektelen cikkek."""
    need = [i for i in ids if LIGHT.get(i, {}).get("v") == 4 and not LIGHT[i]["cats"] and not LIGHT[i]["sight"]
            and not LIGHT[i]["skip"] and LIGHT[i]["title"] and LIGHT[i]["len"] >= 2500]
    chunks = [need[k:k + 50] for k in range(0, len(need), 50)]

    def work(ch):
        return wiki_query_all({"action": "query", "pageids": "|".join(str(x) for x in ch),
                               "prop": "categories", "cllimit": "max", "clshow": "!hidden"})

    with ThreadPoolExecutor(max_workers=3) as ex:
        for ch, info in zip(chunks, ex.map(work, chunks)):
            for pid in ch:
                p = info.get(pid, {})
                cats = [c.get("title", "").replace("Kategória:", "") for c in p.get("categories", [])]
                L = LIGHT[pid]
                L["sight"] = is_sight(L["desc"], cats)
                L["tw"] = type_weight(L["desc"], cats, L["title"])
                L["cats"] = 1
    for i in ids:
        if i in LIGHT and LIGHT[i].get("v") == 4:
            LIGHT[i]["cats"] = 1


def select_ids(ids, sights_only, min_tier, tick=None):
    """A jeloltekbol azok, amelyek latnivalok es legalabb min_tier jelentosegueek. Tick: allapot-visszahivas."""
    for k in range(0, len(ids), 300):
        lite_info(ids[k:k + 300])
        if tick:
            tick("ellenőrzés %d%% (%d Wikipédia-kérés, %d újrapróbálás, %.0f mp várakozás, utolsó hiba: %s)" % (min(100, 100 * (k + 300) // max(1, len(ids))), WSTAT["req"], WSTAT["retry"], WSTAT["slow"], WSTAT["code"] or "nincs"))
    if sights_only:
        if tick:
            tick("kategóriák")
        cats_info(ids)
    ok = [i for i in ids if LIGHT[i].get("title") and not LIGHT[i].get("skip") and (LIGHT[i]["sight"] or not sights_only)]
    if tick:
        tick("jelentőség felmérése")
    sitelinks_info([LIGHT[i].get("qid") for i in ok if LIGHT[i].get("len", 0) >= 500])
    if sights_only:                    # kiemelkedo, sok nyelven szocikkel rendelkezo hely akkor is latnivalo, ha a rovid leirasa ezt nem mondja ki (pl. Orszaghaz)
        extra = [i for i in ids if LIGHT[i].get("title") and not LIGHT[i].get("skip") and not LIGHT[i]["sight"] and LIGHT[i].get("len", 0) >= 8000]
        if extra:
            sitelinks_info([LIGHT[i].get("qid") for i in extra])
            for i in extra:
                if SLC.get(LIGHT[i].get("qid", ""), 0) >= 40 and not TRIVIAL.search(LIGHT[i]["title"] + " " + LIGHT[i].get("desc", "")):
                    LIGHT[i]["sight"] = True
                    ok.append(i)
    return ok, [i for i in ok if tier_of(i) >= min_tier]


def sitelinks_info(qids, budget=30.0):
    """Nyelvi valtozatok szama (jelentoseg). Ido-keretes: ami nem fer bele, hatterben toltodik, a lista addig alapertekkel dolgozik."""
    need = [q for q in dict.fromkeys(qids) if q and (q not in SLC or q not in SLH) and re.match(r"^Q\d+$", q)]
    chunks = [need[k:k + 25] for k in range(0, len(need), 25)]
    t0 = time.time()
    for n_, ch in enumerate(chunks):
        if budget is not None and time.time() - t0 > budget:
            rest = [q for c_ in chunks[n_:] for q in c_]
            if not SL_BG[0]:
                SL_BG[0] = True

                def bg():
                    try:
                        sitelinks_info(rest, None)
                        save_cache()
                    finally:
                        SL_BG[0] = False
                threading.Thread(target=bg, daemon=True).start()
            return
        try:
            r = wiki_get({"action": "wbgetentities", "ids": "|".join(ch), "props": "sitelinks"},
                         api=WIKIDATA_API, fv2=False)
        except Exception:
            continue
        ents = r.get("entities", {})
        for q in ch:
            e = ents.get(q) or {}
            sl = e.get("sitelinks") or {}
            SLC[q] = len(sl)
            SLH[q] = (sl.get("huwiki") or {}).get("title", "")


SL_BG = [False]


# ---------- Wikidata-gyorskereses: a jelentos helyek forrasnal szurve, egy SPARQL-kerdessel csempenkent ----------
SPARQL_API = "https://query.wikidata.org/sparql"
WDQ = {"fail": 0, "bad": 0.0, "last": "", "pre": "", "stop": False}   # allapot / diagnosztika
WDT = {}      # csempe-kulcs -> [[qid, nyelvszam, hu cim, en cim, lat, lon], ...] (gyorsitotarba mentve)
HUT = {}      # magyar cikkcim -> oldalazonosito (0 = nincs)
ENT = {}      # angol cikkcim -> oldalazonosito
WD_TILE = 0.5
WD_MINSL = 4      # legalabb ennyi nyelven letezo helyek (a magyar cikkel rendelkezoknel)
WD_EN_MINSL = 7   # angol-csak helyeknel szigorubb
_wd_sem = threading.Semaphore(1)


def wd_sparql(query):
    url = SPARQL_API + "?" + urllib.parse.urlencode({"query": query, "format": "json"})
    for attempt in range(3):
        try:
            with _wd_sem:
                req = urllib.request.Request(url, headers={"User-Agent": UA, "Accept": "application/sparql-results+json"})
                with urllib.request.urlopen(req, timeout=75) as r:
                    return json.loads(r.read().decode("utf-8"))
        except urllib.error.HTTPError as e:
            if e.code in (429, 503, 504) and attempt < 2:
                ra = e.headers.get("Retry-After") if e.headers else None
                time.sleep(min(20.0, float(ra) if ra and ra.strip().isdigit() else 5.0 * (attempt + 1)))
                continue
            raise
        except Exception:
            if attempt < 1:
                time.sleep(2)
                continue
            raise


def _wtitle(b):
    if not b:
        return ""
    v = b.get("value", "")
    return urllib.parse.unquote(v.rsplit("/wiki/", 1)[1]).replace("_", " ") if "/wiki/" in v else ""


def wd_tile(i, j):
    key = "%d,%d,%d" % (i, j, WD_MINSL)
    if key in WDT:
        return WDT[key]
    s, w = i * WD_TILE, j * WD_TILE
    n, e = s + WD_TILE, w + WD_TILE
    q = ('SELECT ?item ?c ?sl ?hu ?en WHERE { SERVICE wikibase:box { ?item wdt:P625 ?c . '
         'bd:serviceParam wikibase:cornerSouthWest "Point(%.4f %.4f)"^^geo:wktLiteral . '
         'bd:serviceParam wikibase:cornerNorthEast "Point(%.4f %.4f)"^^geo:wktLiteral . } '
         '?item wikibase:sitelinks ?sl . FILTER(?sl >= %d) '
         'OPTIONAL { ?hu schema:about ?item ; schema:isPartOf <https://hu.wikipedia.org/> . } '
         'OPTIONAL { ?en schema:about ?item ; schema:isPartOf <https://en.wikipedia.org/> . } }') % (w, s, e, n, WD_MINSL)
    js = wd_sparql(q)
    out = {}
    for b in js["results"]["bindings"]:
        try:
            qid = b["item"]["value"].rsplit("/", 1)[1]
            m = re.match(r"Point\(([-0-9.eE+]+) ([-0-9.eE+]+)\)", b["c"]["value"])
            if not m or not re.match(r"^Q\d+$", qid):
                continue
            out.setdefault(qid, [qid, int(float(b["sl"]["value"])), _wtitle(b.get("hu")), _wtitle(b.get("en")),
                                 float(m.group(2)), float(m.group(1))])
        except (KeyError, ValueError, IndexError):
            continue
    WDT[key] = list(out.values())
    return WDT[key]


def wd_tiles_for(samples, lo, hi, Wc):
    """A szakaszt lefedo csempek (az utvonal menten sorrendben)."""
    tiles = {}
    for p in samples:
        if not (lo - Wc <= p[2] <= hi + Wc):
            continue
        dl = Wc / 111.32
        dn = Wc / (111.32 * max(0.05, math.cos(math.radians(p[0]))))
        for i in range(int(math.floor((p[0] - dl) / WD_TILE)), int(math.floor((p[0] + dl) / WD_TILE)) + 1):
            for j in range(int(math.floor((p[1] - dn) / WD_TILE)), int(math.floor((p[1] + dn) / WD_TILE)) + 1):
                tiles.setdefault((i, j), 1)
    return list(tiles)


def wd_items(lo, hi, Wc, tick=None):
    """A [lo,hi) km-es utvonalszakasz jelentos helyei (Wikidata): [qid, sl, hu, en, lat, lon, along, cross]."""
    tl = wd_tiles_for(ROUTE["samples"], lo, hi, Wc)
    seen, out = set(), []
    for n_, (i, j) in enumerate(tl):
        if tick:
            tick("Wikidata-szűrés %d/%d csempe" % (n_ + 1, len(tl)))
        for it in wd_tile(i, j):
            if it[0] in seen:
                continue
            r = route_nearest(it[4], it[5], Wc)
            if r and lo <= r[0] < hi:
                seen.add(it[0])
                out.append(it + [r[0], r[1]])
    for it in out:
        SLC[it[0]] = it[1]
        SLH[it[0]] = it[2]
    return out


def _rec_hu(p):
    desc = (p.get("description") or "").strip()
    title = p.get("title", "")
    return {"title": title, "desc": desc, "skip": bool(SKIP_DESC.match(desc)), "sight": bool(SIGHT_RE.search(desc)),
            "len": int(p.get("length") or 0), "qid": (p.get("pageprops") or {}).get("wikibase_item", ""),
            "tw": type_weight(desc, [], title), "v": 4, "cats": 0}


def _rec_en(p):
    desc = (p.get("description") or "").strip()
    title = p.get("title", "")
    return {"title": title, "desc": desc, "skip": bool(EN_SKIP.match(desc)), "sight": bool(EN_SIGHT.search(desc)),
            "settle": bool(EN_SETTLE.match(desc)), "len": int(p.get("length") or 0),
            "qid": (p.get("pageprops") or {}).get("wikibase_item", ""), "tw": en_type_weight(desc, title), "v": 5}


def wd_resolve(titles, en=False, stop=None):
    """Cikkcimek -> oldalazonosito (a konnyu adatokat is eltarolja). Csak a meg ismeretlen cimeket kerdezi le."""
    store, api = (ENT, EN_API) if en else (HUT, WIKI_API)
    need = [t for t in dict.fromkeys(titles) if t and t not in store and "|" not in t]
    for k in range(0, len(need), 50):
        if stop and stop():
            break
        ch = need[k:k + 50]
        r = wiki_get({"action": "query", "titles": "|".join(ch), "prop": "description|info|pageprops",
                      "ppprop": "wikibase_item"}, api=api)
        qy = r.get("query", {})
        norm = {n["from"]: n["to"] for n in qy.get("normalized", [])}
        byt = {p.get("title"): p for p in qy.get("pages", []) if not p.get("missing") and p.get("pageid")}
        for t in ch:
            p = byt.get(norm.get(t, t))
            if not p:
                store[t] = 0
                continue
            pid = p["pageid"]
            store[t] = pid
            if en:
                if LIGHT_EN.get(pid, {}).get("v") != 5:
                    LIGHT_EN[pid] = _rec_en(p)
            elif LIGHT.get(pid, {}).get("v") != 4:
                LIGHT[pid] = _rec_hu(p)
    return {t: store.get(t, 0) for t in titles}


def wd_prefetch(bbox):
    """Hatterben: a terseg osszes jelentos helyenek elotoltese (csempek + cikk-azonositok), hogy az utvonalak azonnal keszuljenek."""
    south, west, north, east = bbox
    WDQ["stop"] = False
    try:
        tl = [(i, j) for i in range(int(math.floor(south / WD_TILE)), int(math.floor(north / WD_TILE)) + 1)
              for j in range(int(math.floor(west / WD_TILE)), int(math.floor(east / WD_TILE)) + 1)]
        for n_, (i, j) in enumerate(tl):
            if WDQ["stop"]:
                WDQ["pre"] = "Előtöltés megszakítva"
                return
            WDQ["pre"] = "Előtöltés: Wikidata-csempék %d/%d" % (n_ + 1, len(tl))
            wd_tile(i, j)
            if n_ % 6 == 5:
                save_cache()
        hut = [it[2] for i, j in tl for it in WDT.get("%d,%d,%d" % (i, j, WD_MINSL), []) if it[2]]
        need = [t for t in dict.fromkeys(hut) if t not in HUT]
        for k in range(0, len(need), 50):
            if WDQ["stop"]:
                WDQ["pre"] = "Előtöltés megszakítva"
                return
            WDQ["pre"] = "Előtöltés: cikkek %d/%d" % (min(k + 50, len(need)), len(need))
            wd_resolve(need[k:k + 50])
            if (k // 50) % 8 == 7:
                save_cache()
        for it in [it for i, j in tl for it in WDT.get("%d,%d,%d" % (i, j, WD_MINSL), [])]:
            SLC[it[0]] = it[1]
            SLH[it[0]] = it[2]
        save_cache()
        WDQ["pre"] = "Előtöltés kész (%d csempe, %d cikk)" % (len(tl), len(need))
    except Exception as e:
        WDQ["pre"] = "Előtöltés hiba: %s" % str(e)[:100]




