def vis_key(p):
    pid = p["id"]
    return ("hu:%d" % pid) if isinstance(pid, int) else str(pid)


def vis_enrich(pois, alive, status=None, prompt=None):
    """Hianyzo 'hogyan ismered fel' leirasok kotegelve (20 hely / hivas). Visszaadja, hogy volt-e uj eredmeny."""
    with lock:
        key, model = S["gemini_key"], S["gemini_model"] or "gemini-3.5-flash-lite"
    if not key:
        return False
    need = [p for p in pois if not p.get("visual") and vis_key(p) not in VIS and (p.get("extract") or p.get("desc"))]
    got_new = False
    for i in range(0, len(need), 20):
        if not alive():
            break
        batch = need[i:i + 20]
        items = [{"id": vis_key(p), "name": p["title"], "kind": p.get("desc", ""), "text": (p.get("extract") or "")[:700]} for p in batch]
        if status:
            status("hogyan ismerhető fel a levegőből… %d/%d" % (min(i + 20, len(need)), len(need)))
        res = gemini_call(items, key, model, prompt or VIS_PROMPT)
        rm = {str(r.get("id")): (r.get("visual") or "").strip() for r in res if isinstance(r, dict)}
        for p in batch:
            k_ = vis_key(p)
            if k_ in rm:
                VIS[k_] = rm[k_]
                got_new = True
    return got_new


