VIS_BG = {"busy": False, "last": 0.0}


def vis_auto_kick(out):
    """A kozeli, meg 'visual' nelkuli helyek kotegelt (max 20 / hivas) hattertoltese. Kulcs + napi keret kell."""
    try:
        if not S.get("vis_auto", True) or not S.get("gemini_key") or VIS_BG["busy"] or desc_foreign():
            return
        for p in out:
            if not p.get("visual") and VIS.get(vis_key(p)):
                p["visual"] = VIS[vis_key(p)]
        now = time.time()
        if now - VIS_BG["last"] < 20:
            return
        mx, used = S["ai_daily_max"], S["ai_calls"].get("n", 0)
        if mx > 0 and used >= mx - 5:      # tartalek a leirasoknak
            return
        need = [p for p in out[:30] if not p.get("visual") and vis_key(p) not in VIS and (p.get("extract") or p.get("desc"))
                and vis_key(p) not in VIS_TRIED]
        if len(need) < 3 and not (need and now - VIS_BG["last"] > 90):
            return
        need = need[:20]
        for p in need:
            VIS_TRIED.add(vis_key(p))
        VIS_BG["busy"] = True
        VIS_BG["last"] = now

        def job():
            try:
                if vis_enrich(need, lambda: True):
                    ROUTE["ver"] += 1
                    save_cache()
            except Exception:
                pass
            finally:
                VIS_BG["busy"] = False
        threading.Thread(target=job, daemon=True).start()
    except Exception:
        pass


