def _geo_match(p, api):
    """A GeoNames-hely Wikipedia-cikke: koordinata menti keresés + névegyezés. (oldalazonosito, cim) vagy None."""
    nn = norm_name(p["title"])
    r = wiki_get({"action": "query", "list": "geosearch", "gscoord": "%.5f|%.5f" % (p["lat"], p["lon"]),
                  "gsradius": 3000, "gslimit": 25}, api=api)
    for g in r.get("query", {}).get("geosearch", []):
        tn = norm_name(g.get("title", ""))
        if tn and (tn == nn or (len(nn) >= 5 and (nn in tn or tn in nn))):
            return g["pageid"], g["title"]
    return None


