SEG_KM = 150.0
AI_SEG_KM = 50.0                   # az AI-lista szakaszmerete (kisebb szakasz: egyenletesebb lefedettseg, a modell nem tolti ki Budapesttel a keretet)
CH_KM = SEG_KM                     # az elokeszites szakaszmerete (egyezik az AI-szakasszal)


def ai_segments(W, total, step=None):
    """Az utvonal ~100 km-es szakaszai: (sig, kozeppontok listaja)."""
    samples = ROUTE["samples"]
    out = []
    step = step or SEG_KM
    n = int(total // step) + 1
    for i in range(n):
        a, b = i * step, min(total, (i + 1) * step)
        if b - a < 5 and i > 0:
            continue
        pts = []
        t = a
        while t <= b + 0.1:
            k = min(len(samples) - 1, int(t // 2))
            pts.append([round(samples[k][0], 2), round(samples[k][1], 2)])
            t += 20.0
        sig = hashlib.sha1(json.dumps(pts).encode()).hexdigest()[:16]
        out.append((sig, pts, a))
    return out


def ai_lookup_en(names):
    """Angol Wikipedia-cikkek cimek alapjan: cim -> {pid,title,desc,len,qid,lat,lon} vagy None."""
    res = {}
    need = [n for n in dict.fromkeys(names) if n]
    for k in range(0, len(need), 20):
        ch = need[k:k + 20]
        r = wiki_get({"action": "query", "titles": "|".join(ch), "redirects": 1,
                      "prop": "description|info|pageprops|coordinates", "ppprop": "wikibase_item", "colimit": "max"}, api=EN_API)
        q = r.get("query", {})
        back = {}
        for lst in (q.get("normalized", []), q.get("redirects", [])):
            for m_ in lst:
                back[m_.get("to")] = m_.get("from")
        pages = {p.get("title"): p for p in q.get("pages", [])}
        for t in ch:
            title = t
            seen = 0
            fw = {}
            for lst in (q.get("normalized", []), q.get("redirects", [])):
                for m_ in lst:
                    fw[m_.get("from")] = m_.get("to")
            while title in fw and seen < 4:
                title = fw[title]
                seen += 1
            p = pages.get(title)
            if not p or p.get("missing") or p.get("invalid"):
                res[t] = None
                continue
            co = (p.get("coordinates") or [{}])[0]
            res[t] = {"pid": p.get("pageid"), "title": p.get("title", t), "desc": (p.get("description") or "").strip(),
                      "len": int(p.get("length") or 0), "qid": (p.get("pageprops") or {}).get("wikibase_item", ""),
                      "lat": co.get("lat"), "lon": co.get("lon")}
    return res


def route_ai_cands(W, Wc, hu_qids, have_pids, alive, status, segs=None):
    """AI-javaslatok: (jeloltek, megjegyzes). 'en' tipus: van angol cikk; 'ai' tipus: nincs, a szoveg az AI-tol."""
    with lock:
        key, model = S["gemini_key"], S["gemini_model"] or "gemini-3.5-flash-lite"
    if not (S["ai_on"] and key):
        return [], ""
    segs = segs if segs is not None else ai_segments(W, ROUTE["len"])
    t_end = time.time() + 240.0
    st = {"n": 0, "err": "", "skip": 0, "fatal": ""}

    def one(seg):
        sig, pts, a0 = seg
        if sig in AIC:
            return
        if time.time() > t_end or st["fatal"] or not alive():
            st["skip"] += 1
            return
        try:
            res = gemini_call({"pontok": pts, "sav_km": int(Wc)}, key, model, AI_PROMPT)
        except Exception as e:
            if "HTTP 40" in str(e) or "kvóta" in str(e):
                st["fatal"] = str(e)[:60]
            else:
                st["err"] = "néhány szakasznál nem sikerült az AI-javaslat"
            return
        AIC[sig] = [r for r in res if isinstance(r, dict)][:12]
        st["n"] += 1
        if time.time() - st.get("saved", 0) > 8:
            st["saved"] = time.time()
            save_cache()                                   # a kesz szakaszok ujrainditas utan is megmaradnak
        status("Útvonal: AI-javaslatok %d/%d szakasz…" % (sum(1 for g in segs if g[0] in AIC), len(segs)))
        time.sleep(0.5)

    status("Útvonal: AI-javaslatok kérése (%d szakasz)…" % len(segs))
    with ThreadPoolExecutor(max_workers=3) as ex:
        list(ex.map(one, segs))
    if not alive():
        return [], ""
    note = ""
    if st["fatal"]:
        return [], "az AI-javaslat nem sikerült (%s)" % st["fatal"]
    if st["err"]:
        note = st["err"]
    if st["skip"]:
        note = ("%d szakasz AI-javaslata az időkeret miatt kimaradt, legközelebb folytatom" % st["skip"])
    raw = []
    for sig, pts, a0 in segs:
        raw.extend(AIC.get(sig, []))
    if not raw:
        return [], note
    found = ai_lookup_en([str(r.get("name_en") or "").strip() for r in raw])
    cands, seen_pid = [], set(have_pids)
    for r in raw:
        try:
            imp = max(1, min(3, int(r.get("importance") or 1)))
            rlat, rlon = float(r.get("lat")), float(r.get("lon"))
        except (TypeError, ValueError):
            continue
        pg = found.get(str(r.get("name_en") or "").strip())
        la, lo = rlat, rlon
        if pg and pg["lat"] is not None:
            la, lo = pg["lat"], pg["lon"]
        near = route_nearest(la, lo, Wc)
        if not near:
            continue
        if pg and pg["pid"] and pg["qid"] and pg["qid"] not in hu_qids and pg["pid"] not in seen_pid:
            seen_pid.add(pg["pid"])
            LIGHT_EN[pg["pid"]] = {"title": pg["title"], "desc": pg["desc"], "skip": False, "sight": True, "settle": False,
                                   "len": pg["len"], "qid": pg["qid"], "tw": 2.5, "v": 5}
            cands.append({"kind": "en", "along": near[0], "cross": near[1], "pid": pg["pid"], "lat": la, "lon": lo,
                          "score": 9.0 + 1.5 * imp, "tier": imp, "ai": True})
        elif not pg and (r.get("text") or "").strip() and (r.get("name_hu") or "").strip():
            cands.append({"kind": "ai", "along": near[0], "cross": near[1], "lat": la, "lon": lo,
                          "score": 8.0 + 1.5 * imp, "tier": imp, "title": r["name_hu"].strip(),
                          "kindtxt": (r.get("kind") or "").strip(), "text": r["text"].strip(), "visual": (r.get("visual") or "").strip(),
                          "pid": "ai:" + hashlib.sha1(("%s|%.2f|%.2f" % (r["name_hu"], la, lo)).encode()).hexdigest()[:10]})
    return cands, note


# ---------------------------------------------------------------- szimulator
SIMP = {"pos": None, "t": 0.0}     # a szimulatortol erkezo utolso pozicio
ROUTE_FAR_KM = 150.0


def pos_decide():
    """A hasznalt pozicio: a szimulatore, kiveve ha az az utvonaltol messze van (vagy nincs): akkor az utvonal kezdopontja."""
    with lock:
        if S["manual"]:
            return
        on = S["start_on_route"]
    sp = SIMP["pos"] if time.time() - SIMP["t"] < 6 else None
    pts = ROUTE["pts"]
    use, src = sp, "sim"
    if on and len(pts) >= 2:
        far = sp is None
        if not far:
            sl = (sp["lat"], sp["lon"])
            far = min(_seg_dist_km(sl, pts[i], pts[i + 1]) for i in range(len(pts) - 1)) > ROUTE_FAR_KM
        if far:
            use = {"lat": pts[0][0], "lon": pts[0][1], "alt": 0.0, "gs": 0.0,
                   "hdg": bearing(pts[0][0], pts[0][1], pts[1][0], pts[1][1]) % 360}
            src = "route"
    if use is None:
        return
    with lock:
        if S["manual"]:
            return
        changed = S["pos_src"] != src or (src == "route" and S["pos"] and (abs(S["pos"]["lat"] - use["lat"]) > 1e-6 or abs(S["pos"]["lon"] - use["lon"]) > 1e-6))
        S["pos"] = use
        S["pos_src"] = src
        if changed:
            S["scan_pos"] = None
    if changed:
        scan_request.set()


def pos_loop():
    while True:
        try:
            pos_decide()
        except Exception:
            pass
        time.sleep(2)


AC = {"title": "", "t": 0.0, "raw": ""}


def _ac_clean(x):
    """SimVar szoveg -> olvashato. A lokalizacios kulcsokbol (TT:ATCCOM.AC_MODEL_G36.0.text) kiszedi a modellt."""
    x = re.sub(r"\s+", " ", str(x or "").replace("\x00", "")).strip()
    if not x or x.lower().startswith("b'"):
        return ""
    m = re.search(r"AC_MODEL[_ ]?([A-Za-z0-9][A-Za-z0-9\- ]*?)(?:\.\d+)?(?:\.text)?$", x)
    if m:
        return m.group(1).strip()
    if x.upper().startswith("TT:"):
        return ""
    return x


_AC_MAKERS = [(r"^C\d{3}", "Cessna"), (r"^DA\d", "Diamond"), (r"^SR2", "Cirrus"), (r"^PA\d", "Piper"), (r"^TBM", "Daher"),
              (r"^(A2|A3)\d\d", "Airbus"), (r"^B7\d\d|^B3\d\d", "Boeing"), (r"^(BE|G36|G58)", "Beechcraft"), (r"^DR4", "Robin"),
              (r"^(E1|E2)\d\d", "Embraer"), (r"^CRJ", "Bombardier"), (r"^(DH|DHC)", "de Havilland"), (r"^(AT7|ATR)", "ATR"), (r"^(PC|PC-)\d", "Pilatus"),
              (r"^(XCUB|Cub)", "CubCrafters"), (r"^(MB|MB339)", "Aermacchi")]


def _ac_maker(t, atype=""):
    """A gyarto neve a tipus elé, ha a TITLE-ben nincs benne (pl. 'C172SP G1000' -> 'Cessna C172SP G1000')."""
    at = _ac_clean(atype)
    if at:
        mk = at.title() if at.isupper() else at
        if re.fullmatch(r"[A-Za-z][A-Za-z\- ]{2,24}", at) and mk.lower() not in t.lower() and not re.match(r"^[A-Z]{1,3}\d", at):
            return (mk + " " + t)[:80]
    for rx, mk in _AC_MAKERS:
        if re.match(rx, t, re.I):
            if mk.lower() not in t.lower():
                return (mk + " " + t)[:80]
            break
    return t


def ac_set(title, model="", atype=""):
    t = _ac_clean(title)[:80]
    if not t:
        return False
    m = _ac_clean(model)
    if m and m.lower() not in t.lower() and len(m) <= 12:
        t = (t + " " + m)[:80]
    t = _ac_maker(t, atype)
    AC["title"], AC["t"] = t, time.time()
    AC["raw"] = "TITLE=%s | ATC_MODEL=%s | ATC_TYPE=%s" % (str(title)[:60], str(model)[:60], str(atype)[:60])
    return True


# ---- leszallas-eszleles (SIM_ON_GROUND 0->1): a szimulator sajat 'touchdown' ertekei + gyors mintavetel a G-hez
LD = {"og": None, "air_since": 0.0, "max_agl": 0.0, "fast": False, "post_until": 0.0, "pend": None, "hist": [], "ias": 0.0, "peakg": 0.0, "t_first": 0.0, "n_td": 0}


def _fv(rq, k):
    try:
        v = rq.get(k)
        if v is None or isinstance(v, (bytes, bytearray, str)):
            return None
        return float(v)
    except Exception:
        return None


def ld_finish():
    p = LD["pend"]
    LD["pend"] = None
    if not p:
        return
    p["g"] = round(max(p.get("g") or 0.0, LD["peakg"]), 2) or None
    try:
        a = airport_near(p["lat"], p["lon"], 8.0)
        if a:
            p["apt"] = _short_apt(a)
            p["icao"] = a[0]
    except Exception:
        pass
    if PB["rec"]:
        p["t"] = int(p["ts"] - PB["t0"])
        PB.setdefault("lands", []).append(p)
        PB["save"] = 0.0                         # a kovetkezo tick azonnal mentse
    LD["last"] = p
    LD["stopw"] = p


def ld_step(rq):
    """rq: gyors (100 ms-os cache) AircraftRequests. Minden hivas egy mintavetel."""
    og = _fv(rq, "SIM_ON_GROUND")
    if og is None:
        return
    now = time.time()
    pos = SIMP.get("pos") or {}
    agl = _fv(rq, "PLANE_ALT_ABOVE_GROUND")
    g = _fv(rq, "G_FORCE")
    og = og >= 0.5
    prev = LD["og"]
    LD["og"] = og
    if not og:
        if not LD["air_since"]:
            LD["air_since"] = now
        if prev is True:                                  # elemelkedes (felszallas vagy pattanas)
            LD["leave"], LD["bmax"] = now, 0.0
            LD["stopw"] = None
        if agl is not None:
            LD["max_agl"] = max(LD["max_agl"], agl)
            LD["bmax"] = max(LD.get("bmax", 0.0), agl)
            vs_ = _fv(rq, "VERTICAL_SPEED")
            bank_ = _fv(rq, "PLANE_BANK_DEGREES")
            pit_ = _fv(rq, "PLANE_PITCH_DEGREES")
            LD["hist"].append((now, agl, vs_, bank_, pit_))
            LD["hist"] = [h for h in LD["hist"] if now - h[0] < 2.0]
            hh = [h for h in LD["hist"] if h[1] > 2 and h[2] is not None]          # a VERTICAL_SPEED mertekegysegenek tanulasa az AGL-bol
            if len(hh) >= 2 and hh[-1][0] - hh[0][0] > 0.8:
                slope = (hh[0][1] - hh[-1][1]) / (hh[-1][0] - hh[0][0]) * 60.0
                if slope > 150:
                    mv = sum(abs(h[2]) for h in hh) / len(hh)
                    LD["vsfac"] = 1.0 if mv > 0.3 * slope else 60.0
        ias = _fv(rq, "AIRSPEED_INDICATED")
        if ias is not None:
            LD["ias"] = ias
        LD["fast"] = agl is not None and agl < 250
        if g is not None and LD["pend"] is not None and now - LD["t_first"] < 1.0:
            LD["peakg"] = max(LD["peakg"], g)
        return
    LD["fast"] = False
    if prev is False:
        if LD["pend"] is not None and now - LD["t_first"] < 15:
            if now - LD.get("leave", now) >= 0.3 and LD.get("bmax", 0.0) >= 2.0:      # csak valodi pattanas, nem a futo rugozasa
                LD["pend"]["bounces"] = LD["pend"].get("bounces", 0) + 1
        elif LD["air_since"] and now - LD["air_since"] > 12 and LD["max_agl"] > 40:
            if LD["pend"] is not None:
                ld_finish()
            last = LD["hist"][-1] if LD["hist"] else None
            fps = _fv(rq, "PLANE_TOUCHDOWN_NORMAL_VELOCITY")
            est = False
            vs = abs(fps) * 60.0 if fps is not None and abs(fps) > 0.01 else None
            if vs is None and last is not None and last[2] is not None and now - last[0] < 0.6:
                vs = abs(last[2]) * LD.get("vsfac", 1.0)             # az utolso levegobeli mintavetel (kb. 0,1 mp-cel a foldetes elott)
                if vs < 1 or vs > 4000:
                    vs = None
            if vs is None and len(LD["hist"]) >= 2:                  # tartalek: az AGL meredekseg
                h = [x for x in LD["hist"] if x[1] < 60]
                if len(h) >= 2 and h[-1][0] - h[0][0] > 0.15:
                    vs = max(0.0, (h[0][1] - h[-1][1]) / (h[-1][0] - h[0][0])) * 60.0
                    est = True
            lat = _fv(rq, "PLANE_TOUCHDOWN_LATITUDE")
            lon = _fv(rq, "PLANE_TOUCHDOWN_LONGITUDE")
            if lat is not None and abs(lat) <= 6.4 and lon is not None:       # radian -> fok
                lat, lon = math.degrees(lat), math.degrees(lon)
            if lat is None or lon is None or (abs(lat) < 0.0001 and abs(lon) < 0.0001):
                lat, lon = pos.get("lat"), pos.get("lon")
            if lat is not None:
                def _deg(v, lim=360.0):
                    if v is None:
                        return None
                    d = math.degrees(v)                      # a konyvtar radiant ad; ha igy valoszinutlen, akkor fok
                    return round(d if abs(d) <= lim and abs(v) <= 6.4 else v, 1)
                bank = _deg(_fv(rq, "PLANE_TOUCHDOWN_BANK_DEGREES"), 90.0)
                pitch = _deg(_fv(rq, "PLANE_TOUCHDOWN_PITCH_DEGREES"), 60.0)
                if (bank is None or pitch is None) and last is not None and now - last[0] < 0.6:
                    if bank is None:
                        bank = _deg(last[3], 90.0)
                    if pitch is None and last[4] is not None:
                        pp = _deg(last[4], 60.0)
                        pitch = None if pp is None else -pp          # a SimConnect-ban az orr lefele all pozitiv
                wd, wv, tc = _fv(rq, "AMBIENT_WIND_DIRECTION"), _fv(rq, "AMBIENT_WIND_VELOCITY"), _fv(rq, "AMBIENT_TEMPERATURE")
                LD["n_td"] += 1
                LD["t_first"] = now
                LD["peakg"] = g or 0.0
                LD["pend"] = {"ts": int(now), "lat": round(lat, 5), "lon": round(lon, 5), "vs": int(round(vs)) if vs is not None else None, "est": est,
                              "ias": int(round(LD["ias"])), "gs": int(round(pos.get("gs", 0))), "pitch": pitch, "bank": bank,
                              "hdg": round(pos.get("hdg", 0.0)) if pos.get("hdg") is not None else None,
                              "wdir": int(round(wd)) % 360 if wd is not None else None, "wspd": int(round(wv)) if wv is not None else None,
                              "temp": int(round(tc)) if tc is not None else None, "bounces": 0, "g": g, "ac": AC["title"]}
                LD["post_until"] = now + 3.0
    LD["air_since"] = 0.0
    LD["hist"] = []
    if not LD["pend"]:
        LD["max_agl"] = 0.0
    if g is not None and LD["pend"] is not None and now - LD["t_first"] < 1.0:
        LD["peakg"] = max(LD["peakg"], g)
    sw = LD.get("stopw")
    if sw is not None:                                       # megallasig eltelt ido
        if pos.get("gs", 99) < 3.0 and now - sw["ts"] > 3:
            sw["stop"] = int(now - sw["ts"])
            LD["stopw"] = None
            PB["save"] = 0.0
        elif now - sw["ts"] > 240:
            LD["stopw"] = None
    if LD["pend"] is not None and now - LD["t_first"] > 12:
        ld_finish()


def ld_wait(rq, total=1.0):
    """1 mp varakozas; foldkozelben vagy landolas utan 0,1 mp-es mintavetellel (a G csucs miatt)."""
    end = time.time() + total
    while time.time() < end:
        if rq is not None and (LD["fast"] or LD["post_until"] > time.time() or LD["pend"] is not None):
            try:
                ld_step(rq)
            except Exception:
                pass
        time.sleep(0.1)


SC_BROKEN = [0.0]


class _OutFilter(object):
    """A SimConnect-konyvtar a szimulator bezarasa utan vegtelenul irja az 'OS error: ... 0xc000014b' sort.
    Ezt elnyeli, es jelzi a sim_loop-nak, hogy a kapcsolat megszakadt (ujracsatlakozas)."""
    def __init__(self, inner):
        self._inner = inner

    def write(self, s):
        try:
            if "OS error" in s and ("WinError" in s or "0xc000" in s.lower()):
                SC_BROKEN[0] = time.time()
                return len(s)
        except Exception:
            pass
        return self._inner.write(s)

    def __getattr__(self, k):
        return getattr(self._inner, k)


def sim_loop():
    try:
        if not isinstance(sys.stdout, _OutFilter) and sys.stdout is not None:
            sys.stdout = _OutFilter(sys.stdout)
    except Exception:
        pass
    while True:
        if not S["sim_enabled"]:
            with lock:
                S["sim_conn"] = False
                S["sim_status"] = "Szimulátor: kapcsolat kikapcsolva"
            SIMP["pos"] = None
            time.sleep(1)
            continue
        try:
            from SimConnect import SimConnect, AircraftRequests
        except Exception as e:
            with lock:
                S["sim_status"] = "SimConnect csomag nem tölthető be (%s) – használj kézi pozíciót" % e
            for _ in range(15):
                time.sleep(1)
                if not S["sim_enabled"]:
                    break
            continue
        sm = None
        try:
            sm = SimConnect()
            aq = AircraftRequests(sm, _time=1000)
            try:
                aqf = AircraftRequests(sm, _time=100)
            except Exception:
                aqf = None
            LD.update(og=None, air_since=0.0, max_agl=0.0, fast=False, pend=None, hist=[])
            SC_BROKEN[0] = 0.0
            nopos = 0
            with lock:
                S["sim_status"] = "Szimulátor: csatlakozva"
                S["sim_conn"] = True
                if S["manual"]:                       # csatlakozott szimulatornal nincs kezi pozicio
                    S["manual"] = False
                    S["pos"] = None
                    S["pos_src"] = ""
                    S["scan_pos"] = None
            while True:
                if not S["sim_enabled"]:
                    raise RuntimeError("OFF")
                if SC_BROKEN[0] and time.time() - SC_BROKEN[0] < 10:
                    raise RuntimeError("a szimulátor leállt, a kapcsolat megszakadt")
                lat = aq.get("PLANE_LATITUDE")
                lon = aq.get("PLANE_LONGITUDE")
                alt = aq.get("PLANE_ALTITUDE")
                hdg = aq.get("PLANE_HEADING_DEGREES_TRUE")
                try:
                    hmag = aq.get("PLANE_HEADING_DEGREES_MAGNETIC")
                    hbug = aq.get("AUTOPILOT_HEADING_LOCK_DIR") if S.get("bug_on") else None
                except Exception:
                    hmag = hbug = None
                gs = aq.get("GROUND_VELOCITY")
                try:
                    agl = aq.get("PLANE_ALT_ABOVE_GROUND")
                except Exception:
                    agl = None
                if lat is not None and lon is not None and (abs(lat) > 0.0001 or abs(lon) > 0.0001):
                    h = 0.0
                    if hdg is not None:
                        # a konyvtar radiant ad; ha 6,4-nel nagyobb, fokban van
                        h = float(hdg) if abs(float(hdg)) > 6.4 else math.degrees(float(hdg))
                    SIMP["pos"] = {"lat": float(lat), "lon": float(lon),
                                   "alt": float(alt or 0), "hdg": h % 360,
                                   "gs": float(gs or 0)}
                    if agl is not None:
                        SIMP["pos"]["agl"] = float(agl)
                    try:
                        if hmag is not None:
                            hm = float(hmag) if abs(float(hmag)) > 6.4 else math.degrees(float(hmag))
                            mv = ((h - hm + 540) % 360) - 180
                            if abs(mv) < 60:
                                SIMP["pos"]["mag"] = hm % 360
                                if hbug is not None and 0 <= float(hbug) <= 360:
                                    SIMP["pos"]["bug"] = float(hbug) % 360
                                    SIMP["pos"]["bugt"] = (float(hbug) + mv) % 360
                    except Exception:
                        pass
                    SIMP["t"] = time.time()
                    nopos = 0
                    pos_decide()
                else:
                    nopos += 1
                    if nopos >= 15:
                        raise RuntimeError("nincs pozíciót adó adat (a szimulátor leállt vagy menüben van)")
                if time.time() - AC["t"] > 30:                     # a gep tipusa: ritkan, csak olvasas
                    try:
                        def _av(k):
                            try:
                                v = aq.get(k)
                                return bytes(v).decode("utf-8", "replace") if isinstance(v, (bytes, bytearray)) else (v or "")
                            except Exception:
                                return ""
                        tv = _av("TITLE")
                        if tv:
                            ac_set(tv, _av("ATC_MODEL"), _av("ATC_TYPE"))
                        else:
                            AC["t"] = time.time() - 20
                    except Exception:
                        AC["t"] = time.time() - 20
                if aqf is not None:
                    try:
                        ld_step(aqf)
                    except Exception:
                        pass
                ld_wait(aqf, 1.0)
        except Exception as e:
            try:
                if sm is not None:
                    sm.exit()               # leallitja a konyvtar hatterszalat, ami a hibasort ismetelgetne
            except Exception:
                pass
            with lock:
                S["sim_conn"] = False
                if str(e) == "OFF" or not S["sim_enabled"]:
                    S["sim_status"] = "Szimulátor: kapcsolat kikapcsolva"
                else:
                    S["sim_status"] = "Szimulátor: nincs kapcsolat (%s) – újrapróbálom" % e
            if str(e) != "OFF":
                time.sleep(5)


def report_build(kind, note, imgs=None):
    """Hibajelentes: zip a reports/ mappaban. kind='ui': nincs pozicio; kind='pos': pozicio, utvonal es kereses adatai is bekerulnek."""
    import platform
    import zipfile
    pos_on = (kind == "pos")
    coord = re.compile(r"-?\d{1,3}\.\d{3,}")

    def red(t):
        return t if pos_on else coord.sub("·", t)

    def tail(path, n):
        try:
            with open(path, "rb") as f:
                f.seek(0, 2)
                sz = f.tell()
                f.seek(max(0, sz - n))
                t = f.read().decode("utf-8", "replace")
            return "\n".join(x for x in t.splitlines() if x.strip())
        except Exception:
            return ""

    L = ["AiROGUIDE hibajelentés", "Verzió: %s" % APP_VER, "Idő: %s" % time.strftime("%Y-%m-%d %H:%M:%S"),
         "Rendszer: %s" % platform.platform(), "Python: %s" % sys.version.split()[0],
         "Típus: %s" % ("pozícióhoz / kereséshez / felvételhez kapcsolódó" if pos_on else "megjelenési / kezelési (pozíció nélkül)"), "",
         "Megjegyzés:", (note or "")[:2000], "", "Beállítások:"]
    with lock:
        items = sorted(S.items())
        stat = [(k, S.get(k)) for k in ("sim_status", "scan_status")]
        spos, scpos = S.get("pos"), S.get("scan_pos")
    for k, v in items:
        if re.search(r"key|secret|pass|token|code|mail|url", k, re.I):
            continue
        if not pos_on and re.search(r"pos|lat|lon|home|route|origin", k, re.I):
            continue
        if isinstance(v, (bool, int, float)) or (isinstance(v, str) and len(v) <= 120):
            L.append("  %s = %s" % (k, red(str(v))))
    L += ["", "Állapot:"]
    for k, v in stat + [("route_status", ROUTE.get("status")), ("idx_status", IDX.get("status"))]:
        L.append("  %s: %s" % (k, red(str(v or ""))[:400]))
    L.append("  gép: %s" % (AC.get("title") if time.time() - AC.get("t", 0) < 900 else ""))
    if pos_on:
        L += ["", "Pozíció: %s" % (spos,), "Utolsó keresés helye: %s" % (scpos,), "Keresés adatai: %s" % ({k: v for k, v in SCAN_INFO.items() if isinstance(v, (int, float, str))},),
              "Útvonal: %d pont, %.0f km, %d hely" % (len(ROUTE.get("pts") or []), ROUTE.get("len") or 0, len(ROUTE.get("pois") or [])),
              "Útvonal pontjai (az első 150): %s" % ([list(map(lambda x: round(x, 4), p)) for p in (ROUTE.get("pts") or [])[:150]],)]
    d = os.path.join(APP_DIR, "reports")
    os.makedirs(d, exist_ok=True)
    name = "airoguide_report_%s.zip" % time.strftime("%Y%m%d-%H%M%S")
    path = os.path.join(d, name)
    with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED) as z:
        z.writestr("report.txt", "\n".join(L))
        z.writestr("debug.log", red(tail(DBG_FILE, 150000)))
        z.writestr("console.log", red(tail(os.path.join(APP_DIR, "airoguide_console.log"), 20000)))
        import base64
        for i, u in enumerate((imgs or [])[:3]):
            try:
                if isinstance(u, str) and u.startswith("data:image/") and "," in u:
                    z.writestr("screenshot%d.jpg" % (i + 1), base64.b64decode(u.split(",", 1)[1]))
            except Exception:
                pass
    olds = sorted(x for x in os.listdir(d) if x.startswith("airoguide_report_") and x.endswith(".zip"))
    for x in olds[:-10]:
        try:
            os.remove(os.path.join(d, x))
        except Exception:
            pass
    if os.name == "nt":
        try:
            import subprocess
            subprocess.Popen('explorer /select,"%s"' % path)
        except Exception:
            pass
    return {"ok": True, "path": path, "name": name}


def watchdog_loop():
    """Ha egy kereses 90 mp-nel tovabb tart, kiirja a naplóba az osszes szal pillanatnyi allapotat (hol akadt el)."""
    import traceback as _tb
    seen = 0.0
    while True:
        time.sleep(15)
        try:
            t0 = S.get("scan_t0") or 0.0
            if t0 and time.time() - t0 > 90 and t0 != seen:
                seen = t0
                parts = []
                for tid, fr in sys._current_frames().items():
                    parts.append("--- thread %s\n%s" % (tid, "".join(_tb.format_stack(fr)[-6:])))
                dlog("scan lassu (%.0f s) - szalak:\n%s" % (time.time() - t0, "\n".join(parts)))
        except Exception:
            pass


def scan_loop():
    last_try = 0.0
    while True:
        time.sleep(1)
        with lock:
            pos = dict(S["pos"]) if S["pos"] else None
            auto = S["auto_scan"]
            scan_pos = S["scan_pos"]
            scan_hdg = S["scan_hdg"]
            cone_on = S["cone_on"]
            half = S["cone_half"]
            radius = S["radius_km"]
            sights_only = S["sights_only"]
            source = S["source"]
        if not pos:
            continue
        if route_view(pos) is not None:                 # utvonal-modban a kesz anyagbol dolgozunk, nem keresunk
            scan_request.clear()
            continue
        with lock:
            smp = S.get("scan_more_pos")
            if S.get("scan_more") and smp and hav_km(pos["lat"], pos["lon"], smp[0], smp[1]) > max(30.0, radius * 2):
                S["scan_more"] = 0; S["scan_more_pos"] = None          # messzire repult: a kert extra helyek alaphelyzetbe
        forced = scan_request.is_set()
        moved = scan_pos is None or hav_km(pos["lat"], pos["lon"], scan_pos[0], scan_pos[1]) >= RESCAN_MOVE_KM
        turned = (cone_on and scan_hdg is not None
                  and abs(((pos["hdg"] - scan_hdg + 540) % 360) - 180) >= 30)
        if not (forced or (auto and (moved or turned))):
            continue
        if not forced and time.time() - last_try < 8:
            continue
        scan_request.clear()
        last_try = time.time()
        with lock:
            S["scan_t0"] = time.time(); S["scan_secs"] = None
            dlog("scan start: %.4f,%.4f src=%s desc_lang=%s r=%s" % (pos["lat"], pos["lon"], source, dlang(), radius))
            S["scan_status"] = "Keresés folyamatban (%s)…" % {"idx": "helyi index", "osm": "OpenStreetMap"}.get(source, "Wikipédia")
        def early(p, pos=pos):
            apply_ovr(p)
            with lock:
                S["pois"] = p
                S["scan_status"] = "%d hely megvan, a magyar leírások töltődnek…" % len(p)
        try:
            pois = fetch_pois(pos["lat"], pos["lon"],
                              hdg=pos["hdg"] if cone_on else None,
                              cone_half=min(180.0, half + 30.0) if cone_on else None,
                              radius_km=radius, sights_only=sights_only, source=source, progress=early)
            apply_ovr(pois)
            with lock:
                S["pois"] = pois
                S["scan_pos"] = (pos["lat"], pos["lon"])
                S["scan_hdg"] = pos["hdg"]
            save_cache()
            dlog("scan done: %d places in %.1f s" % (len(pois), time.time() - S["scan_t0"]))
            with lock:
                S["scan_secs"] = round(time.time() - S["scan_t0"], 1); S["scan_t0"] = 0.0
                S["scan_status"] = "%d hely, %d vizsgálva · %s (%s)%s" % (len(pois), SCAN_INFO["cand"], SCAN_INFO["src"], time.strftime("%H:%M:%S") + (", " + SCAN_INFO["timing"] if SCAN_INFO.get("timing") else ""), " · nagyon sűrű terület, a legtávolabbiak kimaradhattak" if SCAN_INFO["capped"] else "") + SCAN_INFO.get("dbg", "")
        except Exception as e:
            import traceback as _tb
            dlog("scan error: %s\n%s" % (e, _tb.format_exc()))
            save_cache()                       # ami addig megvolt, azt megtartjuk
            last_try = time.time() + 22        # hiba utan legalabb ~30 mp szunet
            with lock:
                S["scan_secs"] = round(time.time() - S["scan_t0"], 1); S["scan_t0"] = 0.0
                if "429" in str(e):
                    S["scan_status"] = "A Wikipédia lassításra kért (túl sok kérés), ~30 mp múlva újra próbálom."
                else:
                    S["scan_status"] = "Wikipédia-hiba: %s" % e


def build_state():
    with lock:
        pos = dict(S["pos"]) if S["pos"] else None
        pois = list(S["pois"])
        st = {
            "manual": S["manual"], "sim_status": S["sim_status"], "sim_enabled": S["sim_enabled"], "sim_conn": S["sim_conn"], "welcome_seen": S["welcome_seen"], "tutorial_seen": S["tutorial_seen"], "lang_set": S["lang_set"],
            "scan_status": S["scan_status"], "scan_t0": S["scan_t0"], "scan_secs": S["scan_secs"], "idx_status": IDX["status"], "radius": S["radius_km"],
            "auto_scan": S["auto_scan"], "sights_only": S["sights_only"],
            "cone_on": S["cone_on"], "cone_half": S["cone_half"],
            "autoread": S["autoread"], "narr_dist": S.get("narr_dist", True), "narr_title": S.get("narr_title", True), "narr_desc": S.get("narr_desc", True), "narr_vis": S.get("narr_vis", False), "tts_fb": TTS_FB[0], "narr_order": S.get("narr_order", "title,dist,desc,vis"), "voice": S["voice"], "voice_vol": S["voice_vol"], "voice_rate": S["voice_rate"], "voice_pitch": S["voice_pitch"], "source": S["source"],
            "speaking": S["speaking"], "speak_error": S["speak_error"], "speak_phase": S["speak_phase"],
            "route_on": S["route_on"], "wiki_fill": S.get("wiki_fill", True), "vis_auto": S.get("vis_auto", True), "route_width": S["route_width"], "min_tier": S["min_tier"],
        }
    st["route_want"] = bool(ROUTE.get("want"))
    st["efb_txt"] = ROUTE.get("efb_txt", "")
    st["hidden"] = dict(USER["hidden"])
    st["star_flt"] = S.get("star_flt", "0,1,2,3")
    st["route_status"] = ROUTE["status"] + ((" [indítások: %d; utolsók: %s]" % (ROUTE.get("starts", 0), " | ".join(ROUTE.get("hist", [])[-3:]))) if ROUTE.get("hist") else "")
    st["route_busy"] = bool(ROUTE.get("busy"))
    try:                                                # orzo: ha van utvonal, de nem keszul es nem kesz, 20 mp utan ujrainditjuk
        if ROUTE.get("pts") and not ROUTE["ready"] and not ROUTE.get("busy"):
            t_ = ROUTE.get("idle_t")
            if not t_ or ROUTE.get("idle_g") != ROUTE["gen"]:
                ROUTE["idle_t"], ROUTE["idle_g"] = time.time(), ROUTE["gen"]
            elif time.time() - t_ > 20 and ROUTE.get("wd_g") != ROUTE["gen"]:
                ROUTE["wd_g"] = ROUTE["gen"]
                ROUTE["hist"] = (ROUTE.get("hist") or []) + ["%s újraindítva (nem készült)" % time.strftime("%H:%M:%S")]
                threading.Thread(target=route_run, args=(ROUTE["gen"],), daemon=True).start()
        else:
            ROUTE["idle_t"] = None
    except Exception:
        pass
    st["route_fill"] = bool(ROUTE.get("fill_busy")) and bool(ROUTE["ready"])
    st["gemini_set"] = bool(S["gemini_key"])
    st["text_ahead"] = S["text_ahead"]
    st["alert_on"] = S["alert_on"]
    st["alert_sec"] = S["alert_sec"]
    st["ai_max"] = S["ai_daily_max"]
    st["ai_used"] = S["ai_calls"].get("n", 0) if S["ai_calls"].get("d") == time.strftime("%Y-%m-%d") else 0
    st["provider"] = S["provider"]
    st["gemini_last"] = GEM_LAST[0]
    if S.get("gemini_key") and not GEM_TEST[0] and not GEM_AUTO[0]:
        GEM_AUTO[0] = True
        threading.Thread(target=gem_test_run, daemon=True).start()
    st["gemini_test"] = GEM_TEST[0]
    st["gemini_model"] = S["gemini_model"]
    st["en_on"] = S["en_on"]
    st["wd_on"] = S["wd_on"]
    st["gn_on"] = S["gn_on"]
    st["jit_on"] = S["jit_on"]
    st["jit_km"] = S.get("jit_km", 30)
    st["start_on_route"] = S["start_on_route"]
    st["pos_src"] = S["pos_src"]
    st["pipeline"] = S["pipeline"]
    st["list_max"] = S["list_max"]
    st["list_auto"] = bool(S.get("list_auto", True))
    st["route_pool"] = len(ROUTE.get("pool") or []) if ROUTE["ready"] else 0
    st["near_min"] = S["near_min"]
    st["scan_more"] = S.get("scan_more", 0)
    st["gn_status"] = GN["status"] or ("" if GN["ready"] else "nincs letöltve")
    st["gn_ready"] = GN["ready"]
    st["gn_building"] = GN["building"]
    st["text_mode"] = S["text_mode"]
    st["wd_pre_run"] = bool(WDQ.get("run"))
    st["wd_status"] = WDQ["pre"] or (("Wikidata: utolsó hiba: " + WDQ["last"]) if WDQ["last"] and WDQ["fail"] else "")
    st["ai_on"] = S["ai_on"]
    st["en_status"] = ENIDX["status"]
    st["route_len"] = round(ROUTE["len"], 1) if ROUTE["ready"] else 0
    st["route_gen"] = ROUTE["gen"] * 1000 + ROUTE["ver"]
    st["route_count"] = len(ROUTE["pois"]) if ROUTE["ready"] else 0
    st["route_chunks"] = [[round(c["a"]), round(c["b"]), c["state"], c["n"], c.get("t", "vár")] for c in ROUTE.get("chunks", [])] if ROUTE["ready"] else []
    rv = route_view(pos)
    st["route_mode"] = rv is not None
    st["appver"] = APP_VER
    st["upd"] = {"state": UPD["state"], "latest": UPD["latest"], "notes": UPD["notes"], "err": UPD["err"]}
    st["route_origin"] = ROUTE.get("origin", "") if len(ROUTE["pts"]) >= 2 else ""
    st["route_efb_empty"] = ROUTE.get("efb_empty", 0)
    st["dsc_q"] = (len([k for k in EN_STATE["q"] if k not in EN_OVR]) if desc_foreign() else 0)
    st["dsc_busy"] = bool(EN_STATE.get("busy")) and desc_foreign()
    st["dsc_err"] = (EN_STATE.get("err") or "") if desc_foreign() else ""
    st["dsc_done"] = len(EN_OVR) if desc_foreign() else 0
    st["route_oname"] = ROUTE.get("oname", "")
    st["route_want"] = bool(ROUTE.get("want"))
    out = []
    extra = []
    others = 0
    minor = 0
    if pos and rv is not None:
        s0 = rv[0]
        line = []
        for sp in ROUTE["samples"]:
            if s0 - 3.0 <= sp[2] <= s0 + st["radius"] * 1.5 + 6.0:
                d = hav_km(pos["lat"], pos["lon"], sp[0], sp[1])
                if sp[2] > s0 + st["radius"] + 6.0 and d > st["radius"] + 3.0:
                    continue
                b = bearing(pos["lat"], pos["lon"], sp[0], sp[1])
                line.append([round(d, 2), round(((b - pos["hdg"] + 540) % 360) - 180, 1)])
        st["route_line"] = line[::2] if len(line) > 60 else line
        st["route_s0"] = round(s0, 2)
        st["route_info"] = "útvonalon: %.0f km a %.0f km-ből, ±%.0f km-re az útvonaltól" % (s0, ROUTE["len"], rv[1])
        for p in list(ROUTE["pois"]) + user_route_pois():
            if p["along"] < s0 - 2.0 or p["along"] > s0 + st["radius"] * 1.5:
                continue
            d = hav_km(pos["lat"], pos["lon"], p["lat"], p["lon"])
            if p["along"] > s0 + st["radius"] and d > st["radius"]:        # az utvonal menten messze, de legvonalban a radaron belul van: latszik; kulonben meg nem
                continue
            b = bearing(pos["lat"], pos["lon"], p["lat"], p["lon"])
            rel = ((b - pos["hdg"] + 540) % 360) - 180
            if (st["sights_only"] and not p.get("sight")) or (p.get("tier") is not None and p["tier"] < st["min_tier"] and not p.get("fill") and not p.get("user") and p["id"] not in USER["favs"]):
                if st["sights_only"] and not p.get("sight"):
                    others += 1
                else:
                    minor += 1
                extra.append({"id": p["id"], "dist": round(d, 2), "rel": int(round(rel)), "title": p.get("title", "")})
                continue
            q = dict(p)
            q.update({"dist": round(d, 2), "brg": int(round(b)) % 360,
                      "rel": int(round(rel)), "side": side_of(rel), "sec": sector8(rel),
                      "eta": eta_sec(pos.get("gs"), p["along"] - s0) if p["along"] >= s0 - 0.3 else None})
            out.append(q)
        out.sort(key=lambda x: x["along"])
    elif pos:
        for p in user_merge(pois):
            d = hav_km(pos["lat"], pos["lon"], p["lat"], p["lon"])
            if d > st["radius"] + 0.001:
                continue
            b0 = bearing(pos["lat"], pos["lon"], p["lat"], p["lon"])
            rel0 = ((b0 - pos["hdg"] + 540) % 360) - 180
            if st["cone_on"] and abs(rel0) > st["cone_half"]:
                continue
            if st["sights_only"] and not p.get("sight"):
                others += 1
                continue
            if p.get("tier") is not None and p["tier"] < st["min_tier"] and not p.get("fill") and not p.get("user") and p["id"] not in USER["favs"]:
                minor += 1
                continue
            b = bearing(pos["lat"], pos["lon"], p["lat"], p["lon"])
            rel = ((b - pos["hdg"] + 540) % 360) - 180
            q = dict(p)
            fwd = d * math.cos(math.radians(rel))
            q.update({"dist": round(d, 2), "brg": int(round(b)) % 360,
                      "rel": int(round(rel)), "side": side_of(rel), "sec": sector8(rel),
                      "eta": eta_sec(pos.get("gs"), fwd) if fwd > 0 else None})
            out.append(q)
        out.sort(key=lambda x: x["dist"])
    st["others"] = others
    st["minor"] = minor
    st["radar_extra"] = extra
    st["pos"] = pos
    if desc_foreign():
        en_apply(out)
    vis_auto_kick(out)
    st["pois"] = user_mark(out)
    st["pb"] = pb_status()
    st["lang"] = S.get("lang", "hu")
    st["dlang"] = dlang()
    st["vlang"] = vlang()
    st["bug_on"] = bool(S.get("bug_on"))
    st["units"] = {"map": S.get("units_map", "nm,ft,kt"), "log": S.get("units_log", "nm,ft,kt")}
    st["ufav"] = len(USER["favs"])
    if S.get("lang", "hu") != "hu":
        tr_state(st)
    return st


# ---------------------------------------------------------------- hang (edge-tts)
_TTS_LOCAL = threading.local()
TTS_FB = [0]            # hanyszor nem fogadta el a szolgaltatas a nyelv-megadast
_TTS_PATCHED = [False]


def _tts_patch():
    """A tobbnyelvu edge-hangok maguk talaljak ki a szoveg nyelvet; a nemzetkozi nevek miatt ez hibas lehet. A <lang xml:lang> SSML-cimke
    kenyszeriti a kivant nyelvet. A csomag belso fuggvenyet (mkssml) csomagoljuk: az eredmenyt utofeldolgozzuk, igy a csomag verziojatol fuggetlen."""
    if _TTS_PATCHED[0]:
        return
    import edge_tts.communicate as ec
    orig = getattr(ec, "mkssml", None)
    if orig is None:
        _TTS_PATCHED[0] = True
        return

    def wrapped(*a, **k):
        out = orig(*a, **k)
        var = getattr(_TTS_LOCAL, "var", "")
        if var:                                   # nyelv-teszt: a megadott jelzesi modszer
            L = "hu-HU"
            if var in ("B", "D"):
                out = re.sub(r"(<speak[^>]*?xml:lang=)(['\"])[^'\"]*\2", lambda m: m.group(1) + "'" + L + "'", out, count=1)
            if var in ("C", "D") and "<prosody" in out:
                out = out.replace("<prosody", "<lang xml:lang='%s'><prosody" % L, 1).replace("</prosody>", "</prosody></lang>", 1)
            if var == "E":
                out = re.sub(r"<voice name='([^']*)'>", lambda m: "<voice name='%s' xml:lang='%s'>" % (m.group(1), L), out, count=1)
                out = out.replace("<prosody", "<lang xml:lang='%s'><prosody" % L, 1).replace("</prosody>", "</prosody></lang>", 1)
                out = out.replace("<speak ", "<speak xmlns:mstts='https://www.w3.org/2001/mstts' ", 1)
            _TTS_LOCAL.last = out
            return out
        loc = getattr(_TTS_LOCAL, "loc", "")
        if loc and isinstance(out, str) and "<speak" in out:
            out = re.sub(r"(<speak[^>]*?xml:lang=)(['\"])[^'\"]*\2", lambda m: m.group(1) + "'" + loc + "'", out, count=1)
        if loc and isinstance(out, str) and "<prosody" in out and "<lang " not in out:
            out = out.replace("<prosody", "<lang xml:lang='%s'><prosody" % loc, 1).replace("</prosody>", "</prosody></lang>", 1)
        return out
    ec.mkssml = wrapped
    _TTS_PATCHED[0] = True


_HU_ABBR = [(r"(\d)\s*m\s+tszf\.?", r"\1 méter tengerszint feletti"), (r"\btszf\.?", "tengerszint feletti"), (r"(\d)\s*km(?![\wáéíóöőúüű²-])", r"\1 kilométer"),
            (r"(\d)\s*m(?![\wáéíóöőúüű²-])", r"\1 méter"), (r"\bkb\.", "körülbelül"), (r"\bún\.", "úgynevezett"), (r"\bpl\.", "például"), (r"\bill\.", "illetve")]


def tts_norm(text, lang):
    """Magyar felolvasashoz: a roviditeseket es mertekegysegeket kiirja, mert a tobbnyelvu hang ezeken a mondatokon nyelvet valthat."""
    if lang in (None, "", "hu"):
        for a, b in _HU_ABBR:
            text = re.sub(a, b, text)
    return text


def tts_path(text, voice, lang=None):
    import asyncio
    import edge_tts
    text = tts_norm(text[:3000], lang)
    loc = ""     # a szolgaltatas a nyelvcimket elutasitja, ezert nem kuldjuk (a sikertelen proba csak lassitott)
    with lock:
        rate, pitch, vol = int(S["voice_rate"]), int(S["voice_pitch"]), int(S["voice_vol"])
    boost = max(0, vol - 100)
    key = hashlib.sha1(("%s|%s|%d|%d|%d|%s" % (voice, loc, rate, pitch, boost, text)).encode("utf-8")).hexdigest()
    path = os.path.join(CACHE_DIR, key + ".mp3")
    if not os.path.exists(path):
        tmp = path + ".tmp"

        async def run():
            await edge_tts.Communicate(text, voice, rate="%+d%%" % rate, pitch="%+dHz" % pitch, volume="%+d%%" % boost).save(tmp)

        def go(l_):
            _TTS_LOCAL.loc = l_
            try:
                asyncio.run(run())
            finally:
                _TTS_LOCAL.loc = ""

        if loc:
            try:
                _tts_patch()
                go(loc)
                if not os.path.exists(tmp) or os.path.getsize(tmp) < 200:
                    raise RuntimeError("ures hang")
            except ImportError:
                raise
            except Exception:
                try:
                    os.remove(tmp)
                except OSError:
                    pass
                go("")                      # ha a szolgaltatas nem fogadja a cimket, enelkul kerjuk
        else:
            go("")
        os.replace(tmp, path)
    return path


_VOICE_LIST = {"t": 0.0, "v": None, "err": ""}


def voice_for_lang(cur, lang):
    """A hang a felolvasas nyelvehez: tobbnyelvu hang, bongeszo-hang es a nyelv nativ hangjai maradnak; mas nyelv nativ hangja helyett az uj nyelv elso hangja jon."""
    pre = "srv:" if cur.startswith("srv:") else ""
    name = cur[4:] if pre else cur
    if name == "browser" or "Multilingual" in name:
        return cur
    native = [v[0] for v in LANGS[lang]["voices"]]
    return cur if name in native else pre + native[0]


def make_shortcut():
    """Asztali parancsikon (AiROGUIDE.lnk) az app ikonjaval. Csak Windowson; a PowerShell WScript.Shell-jet hasznalja (az Asztal helyet a rendszertol kerdezi, igy OneDrive-os asztalon is jo)."""
    if os.name != "nt":
        return {"ok": False, "error": "Csak Windowson érhető el."}
    try:
        import subprocess
        exe = sys.executable
        pw = os.path.join(os.path.dirname(exe), "pythonw.exe")
        if os.path.exists(pw):
            exe = pw
        env = dict(os.environ)
        env.update({"AG_EXE": exe, "AG_APP": os.path.abspath(__file__), "AG_DIR": APP_DIR, "AG_ICO": os.path.join(APP_DIR, "airoguide.ico")})
        ps = ("$d=[Environment]::GetFolderPath('Desktop');$f=Join-Path $d 'AiROGUIDE.lnk';"
              "$s=(New-Object -ComObject WScript.Shell).CreateShortcut($f);"
              "$s.TargetPath=$env:AG_EXE;$s.Arguments=([char]34)+$env:AG_APP+([char]34);$s.WorkingDirectory=$env:AG_DIR;"
              "if(Test-Path $env:AG_ICO){$s.IconLocation=$env:AG_ICO+',0'};$s.Description='AiROGUIDE';$s.Save();Write-Output $f")
        r = subprocess.run(["powershell", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-Command", ps], env=env, capture_output=True, text=True,
                           timeout=30, creationflags=0x08000000)
        out = (r.stdout or "").strip()
        if r.returncode == 0 and out:
            return {"ok": True, "path": out.splitlines()[-1]}
        return {"ok": False, "error": (r.stderr or out or "PowerShell hiba")[:160]}
    except Exception as e:
        return {"ok": False, "error": str(e)[:160]}


def setup_language(code):
    """Elso inditasi nyelvvalasztas: a felulet (ha van hozza fordítás, kulonben angol), a hang (a nyelv alap ferfi hangja), a felolvasas es a leirasok nyelve."""
    if code not in LANGS:
        return
    male = [v[0] for v in LANGS[code]["voices"] if len(v) > 2 and v[2] == "m"]
    name = male[0] if male else LANGS[code]["voices"][0][0]
    S["lang"] = code if code in UI_LANGS else "en"             # (a hivo mar a lock alatt fut)
    S["dlang"] = code
    S["vlang"] = code
    S["voice"] = ("srv:" if str(S.get("voice") or "").startswith("srv:") else "") + name
    S["lang_set"] = True
    dl_activate()
    EN_STATE["q"] = {}
    try:
        ROUTE["ver"] += 1
    except Exception:
        pass


def voice_check(voice):
    """Elerheto-e az edge-tts hang: telepitve van-e a csomag, van-e halozat, szerepel-e a hang a szolgaltatas listajan."""
    voice = tts_voice(voice)
    try:
        import edge_tts
    except ImportError:
        return {"ok": False, "why": "noedge"}
    import asyncio
    now = time.time()
    if _VOICE_LIST["v"] is None or now - _VOICE_LIST["t"] > 6 * 3600:
        try:
            lst = asyncio.run(edge_tts.list_voices())
            _VOICE_LIST["v"] = set(v.get("ShortName", "") for v in lst)
            _VOICE_LIST["t"] = now
        except Exception as e:
            if _VOICE_LIST["v"] is None:
                return {"ok": None, "why": "offline"}
    if voice in _VOICE_LIST["v"]:
        return {"ok": True, "why": ""}
    return {"ok": False, "why": "novoice"}


def tts_mp3(text, voice, lang=None):
    with open(tts_path(text, voice, lang), "rb") as f:
        return f.read()


# ---- hang lejatszasa a gepen (Windows MCI) - ezt hasznalja az EFB-s felulet
speak_q = queue.Queue()


def mci(cmd):
    import ctypes
    buf = ctypes.create_unicode_buffer(256)
    err = ctypes.windll.winmm.mciSendStringW(cmd, buf, 255, 0)
    return err, buf.value


def play_mp3(path, gen):
    mci("close mtvvoice")
    err, _ = mci('open "%s" type mpegvideo alias mtvvoice' % path)
    if err:
        raise RuntimeError("MCI open hiba (%d)" % err)
    try:
        with lock:
            vol = max(0, min(100, int(S["voice_vol"])))
        mci("setaudio mtvvoice volume to %d" % (vol * 10))
        err, _ = mci("play mtvvoice")
        if err:
            raise RuntimeError("MCI play hiba (%d)" % err)
        with lock:
            if S["speak_gen"] == gen:
                S["speak_phase"] = "play"
        time.sleep(0.2)
        deadline = time.time() + 600
        while time.time() < deadline:
            with lock:
                if S["speak_gen"] != gen:
                    break
            err, mode = mci("status mtvvoice mode")
            if err or mode == "stopped":
                break
            time.sleep(0.1)
    finally:
        mci("stop mtvvoice")
        mci("close mtvvoice")


def speaker_loop():
    while True:
        text, voice, gen, lang = speak_q.get()
        while True:                      # mindig a legujabb kerest mondjuk be
            try:
                text, voice, gen, lang = speak_q.get_nowait()
            except queue.Empty:
                break
        try:
            with lock:
                if S["speak_gen"] != gen:
                    continue
            path = tts_path(text, voice, lang)
            with lock:
                current = S["speak_gen"] == gen
            if current:
                play_mp3(path, gen)
        except ImportError:
            with lock:
                if S["speak_gen"] == gen:
                    S["speak_error"] = "Az edge-tts csomag nincs telepítve (futtasd újra a start.bat-ot)."
        except Exception as e:
            with lock:
                if S["speak_gen"] == gen:
                    S["speak_error"] = "Hang hiba: %s" % e
        finally:
            with lock:
                if S["speak_gen"] == gen:
                    S["speaking"] = False
                    S["speak_phase"] = ""


