def _route_len(pts):
    return sum(hav_km(pts[i][1], pts[i][2], pts[i + 1][1], pts[i + 1][2]) for i in range(len(pts) - 1))


def _route_line_out(maxn=260):
    sm = ROUTE.get("samples") or []
    if len(sm) <= maxn:
        return [[round(p[0], 4), round(p[1], 4), round(p[2], 1)] for p in sm]
    step = len(sm) / float(maxn)
    out = [sm[int(i * step)] for i in range(maxn)] + [sm[-1]]
    return [[round(p[0], 4), round(p[1], 4), round(p[2], 1)] for p in out]


def builtin_list():
    return [{"id": r["id"], "name": r["name"], "desc": r["desc"], "km": round(_route_len(r["pts"])),
             "alt_ft": r["alt_ft"], "kt": r["kt"], "n": len(r["pts"])} for r in BUILTIN_ROUTES]


def _dms(v, pos, neg):
    h = pos if v >= 0 else neg
    v = abs(v)
    d = int(v)
    m = int((v - d) * 60)
    sec = (v - d - m / 60.0) * 3600
    return "%s%d\u00b0 %d' %.2f\"" % (h, d, m, sec)


def _lla(la, lo, alt):
    return "%s,%s,+%06.2f" % (_dms(la, "N", "S"), _dms(lo, "E", "W"), alt)


def builtin_pln(rid):
    r = next((x for x in BUILTIN_ROUTES if x["id"] == rid), None) or WH_PLANS.get(rid)
    if not r:
        return None
    alt = r["alt_ft"]
    p = r["pts"]
    esc = lambda t: (t or "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    out = ['<?xml version="1.0" encoding="UTF-8"?>', '<SimBase.Document Type="AceXML" version="1,0">', "  <Descr>AceXML Document</Descr>",
           "  <FlightPlan.FlightPlan>", "    <Title>%s</Title>" % esc(r["name"]), "    <FPType>VFR</FPType>", "    <RouteType>Direct</RouteType>",
           "    <CruisingAlt>%d.000</CruisingAlt>" % alt, "    <DepartureID>%s</DepartureID>" % esc(p[0][0].split()[0][:8]),
           "    <DepartureLLA>%s</DepartureLLA>" % _lla(p[0][1], p[0][2], 0), "    <DestinationID>%s</DestinationID>" % esc(p[-1][0].split()[0][:8]),
           "    <DestinationLLA>%s</DestinationLLA>" % _lla(p[-1][1], p[-1][2], 0), "    <Descr>%s</Descr>" % esc(r["name"]),
           "    <DepartureName>%s</DepartureName>" % esc(p[0][0]), "    <DestinationName>%s</DestinationName>" % esc(p[-1][0]),
           "    <AppVersion><AppVersionMajor>11</AppVersionMajor><AppVersionBuild>282174</AppVersionBuild></AppVersion>"]
    for i, (nm, la, lo) in enumerate(p):
        wid = "%s%d" % (re.sub(r"[^A-Za-z0-9]", "", nm)[:10] or "WP", i + 1)
        out += ['    <ATCWaypoint id="%s">' % wid, "      <ATCWaypointType>User</ATCWaypointType>",
                "      <WorldPosition>%s</WorldPosition>" % _lla(la, lo, alt), "    </ATCWaypoint>"]
    out += ["  </FlightPlan.FlightPlan>", "</SimBase.Document>", ""]
    return "\r\n".join(out)


BUG_URL = "https://discord.gg/kZUD4adc2U"          # ide kerul a Discord meghivo / hibabejelento csatorna linkje; ures: a gomb jelzi, hogy meg nincs beallitva
