_PLN_POS = re.compile(r"<WorldPosition>\s*([NS])\s*(\d+)\D+?(\d+)\D+?([\d.]+)\D*?,\s*([EW])\s*(\d+)\D+?(\d+)\D+?([\d.]+)", re.S)


def pln_points(text):
    """MSFS .pln (AceXML): a repulesi terv pontjai sorrendben [(lat, lon), ...]."""
    pts = []
    for m in _PLN_POS.finditer(text or ""):
        la = int(m.group(2)) + int(m.group(3)) / 60.0 + float(m.group(4)) / 3600.0
        lo = int(m.group(6)) + int(m.group(7)) / 60.0 + float(m.group(8)) / 3600.0
        if m.group(1) == "S":
            la = -la
        if m.group(5) == "W":
            lo = -lo
        if -90 <= la <= 90 and -180 <= lo <= 180:
            pts.append((round(la, 5), round(lo, 5)))
    return pts


def pln_load(text):
    pts = pln_points(text)
    if len(pts) < 2:
        return {"ok": False, "error": "A fájlban nem találtam legalább két útvonalpontot (.pln kell)."}
    tm = re.search(r"<Title>(.*?)</Title>", text or "", re.S)
    ROUTE["want"] = False
    with lock:
        S["manual"] = False
        S["pos_src"] = ""
        S["scan_pos"] = None
    route_set(pts, force=True, why="saját .pln: %s" % ((tm.group(1).strip() if tm else "")[:60]), manual=True, fixed=[])
    ROUTE["origin"], ROUTE["oname"] = "pln", (tm.group(1).strip() if tm else "")[:80]
    route_save()
    sr_add("pln", (tm.group(1).strip() if tm else ""), pts)
    try:
        pos_decide()
    except Exception:
        pass
    return {"ok": True, "n": len(pts), "km": round(_route_len([("", a, b) for a, b in pts])), "title": (tm.group(1).strip() if tm else "")[:80]}


def builtin_load(rid):
    r = next((x for x in BUILTIN_ROUTES if x["id"] == rid), None) or WH_PLANS.get(rid)
    if not r:
        return False
    ROUTE["want"] = False
    with lock:                                    # a kezi pozicio ne tartsa vissza: az utvonal kezdopontjarol (vagy a szimulatorbol) induljunk
        S["manual"] = False
        S["pos_src"] = ""
        S["scan_pos"] = None
    route_set([(la, lo) for _n, la, lo in r["pts"]], force=True, why="beépített útvonal: %s" % r["name"], manual=True, fixed=[])
    ROUTE["origin"], ROUTE["oname"] = ("ai" if rid.startswith("ai") else "builtin"), str(r["name"])[:80]
    route_save()
    if rid.startswith("ai"):
        sr_add("wh", str(r["name"]), [(la, lo) for _n, la, lo in r["pts"]])
    try:
        pos_decide()
    except Exception:
        pass
    return True


# ---------------------------------------------------------------- Mentett utvonalak (pln / EFB / tervezett / lerepult)
SR_FILE = os.path.join(APP_DIR, "airoguide_routes.json")
SR = {"items": []}
SR_MAX = 300


def sr_load():
    try:
        with open(SR_FILE, "r", encoding="utf-8") as f:
            d = json.load(f)
        SR["items"] = [x for x in d.get("items", []) if isinstance(x, dict) and len(x.get("pts") or []) >= 2][:SR_MAX]
    except Exception:
        pass


def sr_save():
    try:
        with open(SR_FILE, "w", encoding="utf-8") as f:
            json.dump({"items": SR["items"]}, f)
    except Exception:
        pass


def _sr_thin(pts, cap=300):
    out = []
    for la, lo in pts:
        if out and hav_km(out[-1][0], out[-1][1], la, lo) < 1.0:
            continue
        out.append((round(float(la), 5), round(float(lo), 5)))
    last = (round(float(pts[-1][0]), 5), round(float(pts[-1][1]), 5))
    if out[-1] != last:
        out.append(last)
    if len(out) > cap:
        step = (len(out) - 1) / float(cap - 1)
        out = [out[int(round(i * step))] for i in range(cap)]
    return out


def _sr_ends(pts):
    try:
        a, b = airport_near(pts[0][0], pts[0][1], 15.0), airport_near(pts[-1][0], pts[-1][1], 15.0)
        if a and b:
            return "%s → %s" % (a[0], b[0])
        if a:
            return "%s →" % a[0]
        if b:
            return "→ %s" % b[0]
    except Exception:
        pass
    return ""


def sr_add(src, name, pts, fixed=None):
    """Elmenti az utvonalat (azonos utvonal: csak a datum / nev frissul)."""
    try:
        pts = [(float(a), float(b)) for a, b in pts]
        if len(pts) < 2:
            return
        thin = _sr_thin(pts)
        if len(thin) < 2:
            return
        sig = hashlib.sha1(("%.3f,%.3f|%.3f,%.3f|%d" % (thin[0][0], thin[0][1], thin[-1][0], thin[-1][1], len(thin))).encode()).hexdigest()[:10]
        name = str(name or "").strip()[:80]
        old = next((x for x in SR["items"] if x["id"] == sig), None)
        if old:
            SR["items"].remove(old)
        it = {"id": sig, "name": name or (old or {}).get("name", ""), "src": src, "t": int(time.time()), "pin": bool((old or {}).get("pin")),
              "km": round(_route_len([("", a, b) for a, b in thin])), "n": len(thin), "ends": _sr_ends(thin), "pts": thin}
        if fixed:
            it["fixed"] = fixed
        SR["items"].insert(0, it)
        _sr_trim()
        sr_save()
    except Exception:
        pass


def _sr_trim():
    """Limit fole a legregebbi NEM vedett utvonal torlodik; a vedettek megmaradnak."""
    while len(SR["items"]) > SR_MAX:
        k = next((i for i in range(len(SR["items"]) - 1, -1, -1) if not SR["items"][i].get("pin")), None)
        if k is None:
            break
        del SR["items"][k]


def sr_pin(rid):
    it = next((x for x in SR["items"] if x["id"] == rid), None)
    if not it:
        return False
    it["pin"] = not it.get("pin")
    sr_save()
    return True


def sr_list():
    L = [{k: x.get(k) for k in ("id", "name", "src", "t", "km", "n", "ends", "pin")} for x in SR["items"]]
    return sorted(L, key=lambda x: 0 if x.get("pin") else 1)


def sr_use(rid):
    it = next((x for x in SR["items"] if x["id"] == rid), None)
    if not it:
        return False
    ROUTE["want"] = False
    with lock:
        S["manual"] = False
        S["pos_src"] = ""
        S["scan_pos"] = None
    nm = it.get("name") or it.get("ends") or "mentett útvonal"
    route_set([tuple(p) for p in it["pts"]], force=True, why="mentett útvonal: %s" % nm, manual=True, fixed=(it.get("fixed") or []))
    ROUTE["origin"], ROUTE["oname"] = ({"pln": "pln", "efb": "efb"}.get(it.get("src"), "builtin")), str(nm)[:80]
    route_save()
    it["t"] = int(time.time())
    SR["items"].remove(it)
    SR["items"].insert(0, it)
    sr_save()
    try:
        pos_decide()
    except Exception:
        pass
    return True


def sr_del(rid):
    n = len(SR["items"])
    SR["items"] = [x for x in SR["items"] if x["id"] != rid]
    if len(SR["items"]) != n:
        sr_save()
        return True
    return False


def sr_from_flight(fid):
    d = flight_get(fid)
    if not d or len(d.get("pts") or []) < 2:
        return False
    pts = [(p[1], p[2]) for p in d["pts"] if abs(p[1]) > 1e-6 or abs(p[2]) > 1e-6]
    sr_add("flown", d.get("name") or d.get("aname") or "", pts)
    thin = _sr_thin(pts)
    sig = hashlib.sha1(("%.3f,%.3f|%.3f,%.3f|%d" % (thin[0][0], thin[0][1], thin[-1][0], thin[-1][1], len(thin))).encode()).hexdigest()[:10]
    return sr_use(sig)


