ST_RX = [(re.compile(a), b) for a, b in ST_RULES]


def tr_status(t):
    if not t or not isinstance(t, str):
        return t
    for rx, b in ST_RX:
        t = rx.sub(b, t)
    return t


_ST_KEYS = ("scan_status", "sim_status", "idx_status", "route_status", "route_info", "efb_txt", "en_status",
            "gemini_last", "gemini_test", "gn_status", "wd_status", "err")


def tr_state(st):
    for k in _ST_KEYS:
        if isinstance(st.get(k), str):
            st[k] = tr_status(st[k])
    return st



def en_load():
    try:
        with open(en_file(), "r", encoding="utf-8") as f:
            d = json.load(f)
        EN_OVR.update(d.get("ovr", {}))
        if d.get("tf") != 1:           # egyszeri javitas: a kep es kapcsolt cikk nelkuli, AI-tudasbol keszult szovegek ujrageneralasa (most mar keresi a kepet)
            for k in [k for k, o in EN_OVR.items() if not o.get("thumb") and not o.get("wiki_en") and not o.get("raw") and o.get("extract")]:
                EN_OVR.pop(k, None)
    except Exception:
        pass


def dl_activate():
    """A leirasi nyelv valtasakor: a mostani nyelv gyorsitotarat elmenti, a ruadott nyelvet betolti (nyelvenkent kulon fajl)."""
    code = dlang() if desc_foreign() else EN_CUR[0]
    if code == EN_CUR[0]:
        return
    en_save()
    EN_OVR.clear()
    EN_STATE["q"] = {}
    EN_STATE["route_feed"] = 0
    EN_STATE["fail"] = {}
    EN_CUR[0] = code
    en_load()


def en_save():
    try:
        tmp = en_file() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump({"ovr": EN_OVR, "tf": 1}, f, ensure_ascii=False)
        os.replace(tmp, en_file())
        EN_STATE["last_save"] = time.time()
    except Exception:
        pass


EN_PROMPT_T = (
    "You are a sightseeing guide for a pilot flying low (VFR) in a flight simulator, writing in {L}. The JSON below lists places "
    "(id, name, kind, text, src, lat, lon). The 'text' may be an English Wikipedia introduction, or Hungarian text, or empty; 'name' and 'kind' may be Hungarian. "
    "For every place return a short description the pilot can listen to.\n"
    "Rules: (1) use ONLY facts from 'text' (translate it into {L} if it is in another language) and never invent numbers or years that are not in it; "
    "if 'text' is empty write at most 2 sentences, and only if you are certain about the named place at those coordinates, otherwise leave 'text' empty; "
    "(2) 3-4 sentences, at most 450 characters, natural spoken {L}; (3) 'title' is the commonly used {L} name of the place (the local name if no {L} name is established); "
    "(4) 'kind' is the type of the place in 1-3 {L} words (e.g. glacier, fjord, castle); "
    "(5) 'visual' is ONE sentence in {L} on how to recognise it from the air, ONLY if the text mentions an outer feature (shape, colour, size, surroundings), otherwise empty.\n"
    "Return ONLY a JSON array, one object per place: {{\"id\": \"...\", \"title\": \"...\", \"kind\": \"...\", \"visual\": \"...\", \"text\": \"...\"}}.\n\nINPUT:\n")


def en_prompt():
    return EN_PROMPT_T.format(L=LANGS[dlang()]["en"])


def en_pids(items):
    """Az angol Wikipedia-cikkek oldalazonositoi a poi-khoz: sajat en_pid, hu cikk nyelvi hivatkozasa."""
    out = {}
    hu_need = {}
    for p in items:
        sid = str(p["id"])
        ep = p.get("en_pid") or (int(sid[3:]) if sid.startswith("en:") and sid[3:].isdigit() else 0)
        if ep:
            out[sid] = ep
        elif sid.isdigit():
            hu_need[int(sid)] = sid
        elif p.get("hu_pid"):
            hu_need[int(p["hu_pid"])] = sid
    ids = list(hu_need)
    titles = {}
    for k in range(0, len(ids), 50):
        ch = ids[k:k + 50]
        try:
            r = wiki_get({"action": "query", "pageids": "|".join(str(x) for x in ch), "prop": "langlinks", "lllang": "en", "lllimit": "max"})
            for pg in r.get("query", {}).get("pages", []):
                ll = pg.get("langlinks") or []
                if ll and pg.get("pageid") in hu_need:
                    titles[hu_need[pg["pageid"]]] = ll[0].get("title") or ll[0].get("*") or ""
        except Exception:
            pass
    if titles:
        try:
            pg = _titles_query(list(titles.values()), EN_API)
            for sid, t in titles.items():
                if t in pg:
                    out[sid] = pg[t]["pageid"]
        except Exception:
            pass
    return out


def _first_sentences(t, n=420):
    t = (t or "").strip()
    if len(t) <= n:
        return t
    cut = t[:n]
    k = max(cut.rfind(". "), cut.rfind("! "), cut.rfind("? "))
    return cut[:k + 1] if k > 120 else cut.rstrip() + "…"


def en_resolve(items):
    """Angol cim / leiras a poi-khoz (a hianyzokat osszegyujti, egy Gemini-hivassal). Visszaad: {sid: ov}"""
    if not items:
        return {}
    with lock:
        key, model = S["gemini_key"], S["gemini_model"] or "gemini-3.5-flash-lite"
    pmap = en_pids(items)
    pids = list(set(pmap.values()))
    if pids:
        lite_info_en(pids)
        full_info_en(pids)
    batch = []
    for p in items:
        sid = str(p["id"])
        ep = pmap.get(sid)
        L = LIGHT_EN.get(ep, {}) if ep else {}
        F = FULL_EN.get(ep, {}) if ep else {}
        txt = (F.get("extract") or "")[:1800]
        src = "en" if txt else ""
        if not txt and p.get("extract"):
            txt, src = str(p["extract"])[:1200], "hu"
        batch.append({"id": sid, "name": L.get("title") or p.get("title", ""), "kind": L.get("desc") or p.get("desc", ""), "text": txt,
                      "src": src or "none", "lat": round(p["lat"], 4), "lon": round(p["lon"], 4), "_ep": ep, "_p": p, "_L": L, "_F": F})
    res = {}
    if key:
        gi = [{k: v for k, v in b.items() if not k.startswith("_")} for b in batch]
        try:
            arr = gemini_call(gi, key, model, en_prompt())
            res = {str(r.get("id")): r for r in arr if isinstance(r, dict)}
        except Exception as e:
            EN_STATE["err"] = str(e)[:120]
            res = {}
    miss = {}                      # nincs kapcsolt cikk es nincs kep: az AI angol cimebol megprobaljuk megtalalni az angol cikket (koordinata-ellenorzessel)
    for b in batch:
        r = res.get(b["id"])
        if r and not b["_ep"] and not (b["_F"].get("thumb") or b["_p"].get("thumb")):
            t = str(r.get("title") or "").strip()
            if t:
                miss[b["id"]] = t
    ep2, tt2 = {}, {}
    if miss:
        try:
            pgs = _titles_query(list(miss.values()), EN_API)
            bp = {b["id"]: b["_p"] for b in batch}
            for sid, t in miss.items():
                pg = pgs.get(t)
                if not pg or (pg.get("pageprops") or {}).get("disambiguation"):
                    continue
                co = (pg.get("coordinates") or [{}])[0]
                if co.get("lat") is not None and hav_km(float(co["lat"]), float(co["lon"]), bp[sid]["lat"], bp[sid]["lon"]) > 60:
                    continue
                ep2[sid], tt2[sid] = pg["pageid"], pg.get("title") or t
            if ep2:
                full_info_en(list(set(ep2.values())))
        except Exception:
            ep2, tt2 = {}, {}
    out = {}
    for b in batch:
        sid = b["id"]
        r = res.get(sid)
        F, L, p = b["_F"], b["_L"], b["_p"]
        thumb = F.get("thumb") or p.get("thumb", "") or FULL_EN.get(ep2.get(sid), {}).get("thumb", "")
        if r and ((r.get("text") or "").strip() or (r.get("title") or "").strip()):
            out[sid] = {"title": (str(r.get("title") or "").strip() or b["name"])[:120], "desc": str(r.get("kind") or "").strip()[:60],
                        "extract": str(r.get("text") or "").strip(), "visual": str(r.get("visual") or "").strip(),
                        "thumb": thumb, "wiki_en": L.get("title", "") if b["_ep"] else tt2.get(sid, "")}
        elif not key:
            out[sid] = {"title": L.get("title") or b["name"], "desc": L.get("desc") or "", "extract": _first_sentences(b["text"]) if b["src"] == "en" else "",
                        "visual": "", "thumb": thumb, "wiki_en": L.get("title", "") if b["_ep"] else "", "raw": True}
        else:
            n = EN_STATE["fail"].get(sid, (0, 0))[0] + 1
            EN_STATE["fail"][sid] = (n, time.time() + (600 if n >= 2 else 60))
            if n >= 3:
                out[sid] = {"title": L.get("title") or b["name"], "desc": L.get("desc") or "", "extract": _first_sentences(b["text"]) if b["src"] == "en" else "",
                            "visual": "", "thumb": thumb, "wiki_en": L.get("title", "") if b["_ep"] else "", "raw": True}
    return out


def en_apply(lst, merge=False):
    """A kiadott lista (masolatok) angolra: megvan -> angol szoveg; nincs -> varakozo, es sorba all a feldolgozasra."""
    q = {}
    for p in lst:
        if p.get("user") or p.get("src") == "user":
            continue
        sid = str(p["id"])
        ov = EN_OVR.get(sid)
        if ov:
            p.update({"title": ov["title"] or p.get("title", ""), "desc": ov.get("desc", ""), "extract": ov.get("extract", ""), "visual": ov.get("visual", ""),
                      "thumb": ov.get("thumb") or "", "wiki_en": ov.get("wiki_en", ""), "src": "enx", "lazy": False, "pending": False, "described": True,
                      "en_noinfo": not ov.get("extract")})
            p.pop("wiki", None)
        else:
            th0 = p.get("thumb") or ""                   # a magyar Wikipedia-kep megmarad tartaleknak (az angol cikk kepe elsobbseget elvez)
            p.update({"extract": "", "desc": "", "visual": "", "lazy": False, "pending": False, "described": True, "en_pend": True, "thumb": ""})
            q[sid] = (p.get("dist", 1e9), dict({k: p.get(k) for k in ("id", "title", "desc", "extract", "lat", "lon", "hu_pid", "en_pid")}, thumb=th0))
    # a sor MINDIG egyesitve bovul (a kozeli lista es a teljes utvonallista egymast ne ulje felul), a mar kesz elemek kikerulnek belole
    qq = EN_STATE["q"]
    for sid in [k for k in qq if k in EN_OVR and not EN_OVR[k].get("raw")]:
        qq.pop(sid, None)
    qq.update(q)


def en_loop():
    while True:
        time.sleep(1.5)
        try:
            if not desc_foreign() or EN_STATE["busy"]:
                continue
            with lock:
                has_key = bool(S["gemini_key"])
            now = time.time()
            if now - EN_STATE.get("route_feed", 0) > 8 and ROUTE.get("ready") and ROUTE["pois"]:
                EN_STATE["route_feed"] = now           # az utvonal helyei akkor is sorba allnak, ha a teljes lista meg nincs megnyitva
                en_apply([dict(x) for x in ROUTE["pois"]])
            cand = []
            for sid, (d, p) in list(EN_STATE["q"].items()):
                ov = EN_OVR.get(sid)
                if ov and not (ov.get("raw") and has_key and EN_STATE["fail"].get(sid, (0, 0))[1] < now):
                    continue
                if EN_STATE["fail"].get(sid, (0, 0))[1] > now:
                    continue
                cand.append((d, p))
            for sid, ov in list(EN_OVR.items()):
                pass
            if not cand:
                continue
            cand.sort(key=lambda x: x[0])
            items = [dict(p, extract=p.get("extract") or "") for _d, p in cand[:12]]
            EN_STATE["busy"] = True
            try:
                res = en_resolve(items)
            finally:
                EN_STATE["busy"] = False
            if res:
                EN_OVR.update(res)
                if now - EN_STATE["last_save"] > 5:
                    en_save()
                try:
                    ROUTE["ver"] += 1
                except Exception:
                    pass
        except Exception as e:
            EN_STATE["busy"] = False
            EN_STATE["err"] = str(e)[:120]
            time.sleep(3)


def en_describe(sid):
    p = next((x for x in ROUTE["pois"] if str(x["id"]) == sid), None)
    if not p:
        t = EN_STATE["q"].get(sid)
        p = t[1] if t else None
    if not p:
        return {"ok": False, "error": "unknown place"}
    with lock:
        has_key = bool(S["gemini_key"])
    if not has_key:
        return {"ok": False, "error": "An API key is needed (Settings)."}
    try:
        EN_OVR.pop(sid, None)
        EN_STATE["fail"].pop(sid, None)
        res = en_resolve([dict(p, extract=p.get("extract") or "")])
    except Exception as e:
        return {"ok": False, "error": "Failed: %s" % str(e)[:100]}
    if sid not in res:
        return {"ok": False, "error": "Could not describe this place now, try again later."}
    EN_OVR[sid] = res[sid]
    en_save()
    ROUTE["ver"] += 1
    ov = res[sid]
    return {"ok": True, "msg": "", "poi": {"id": p["id"], "title": ov["title"], "desc": ov["desc"], "extract": ov["extract"], "visual": ov["visual"], "thumb": ov["thumb"],
                                         "wiki_en": ov["wiki_en"], "src": "enx", "lazy": False, "pending": False, "described": True, "en_pend": False}}


