WH = {"busy": False, "status": "", "err": "", "plans": [], "seen": [], "mode": "", "gen": 0}
WH_PLANS = {}            # id -> {name, desc, alt_ft, pts[(nev, lat, lon)], ...}; a builtin_load / builtin_pln is ezt is eli


def wh_apt_find(q, n=8):
    ql = (q or "").strip().lower()
    if not ql:
        return []
    ex, part = [], []
    for a in _apt_load():
        if not a:
            continue
        if a[0].lower() == ql:
            ex.append(a)
        elif ql in a[1].lower() or ql in (a[5] or "").lower():
            part.append(a)
    part.sort(key=lambda a: ({"L": 0, "M": 1, "S": 2}.get(a[4], 3), len(a[1])))
    return (ex + part)[:n]


def _wh_airports(lat, lon, rad_km, big=12, small=8):
    big_l, small_l = [], []
    coslat = max(0.05, math.cos(math.radians(lat)))
    dl = rad_km / 111.0
    for a in _apt_load():
        if not a or abs(a[2] - lat) > dl or abs(a[3] - lon) * coslat > dl:
            continue
        d = hav_km(lat, lon, a[2], a[3])
        if d <= rad_km:
            (small_l if a[4] == "S" else big_l).append((d, a))
    big_l.sort(key=lambda x: x[0])
    small_l.sort(key=lambda x: x[0])
    return [a for _d, a in big_l[:big]] + [a for _d, a in small_l[:small]]


def _wh_apt_json(a):
    return {"icao": a[0], "name": a[1], "city": a[5], "lat": a[2], "lon": a[3], "size": {"L": "large", "M": "medium", "S": "small"}.get(a[4], "small")}


def _wh_tok(t):
    import unicodedata
    t = unicodedata.normalize("NFKD", t or "").encode("ascii", "ignore").decode().lower()
    return {w for w in re.findall(r"[a-z0-9]{4,}", t)}


def _wh_snap(name, lat, lon):
    """Wikipedia-geokereses: van-e a megadott helyen (<=5 km) a nevnek megfelelo cikk? -> (cim, lat, lon, langlinks) vagy None."""
    try:
        r = wiki_get({"action": "query", "list": "geosearch", "gscoord": "%s|%s" % (lat, lon), "gsradius": 5000, "gslimit": 30}, api=EN_API)
        want = _wh_tok(name)
        best = None
        for g in r.get("query", {}).get("geosearch", []):
            if want & _wh_tok(g.get("title", "")):
                if best is None or g.get("dist", 9e9) < best.get("dist", 9e9):
                    best = g
        if not best:
            return None
        ll = 0
        try:
            r2 = wiki_get({"action": "query", "prop": "langlinks", "lllimit": "max", "pageids": best["pageid"]}, api=EN_API)
            pg = (r2.get("query", {}).get("pages") or [{}])[0]
            ll = len(pg.get("langlinks") or [])
        except Exception:
            pass
        return (best.get("title", ""), best["lat"], best["lon"], ll)
    except Exception:
        return None


