        updb.pack(side="right")
        updm = {"msg": ""}

        def upd_click(_e=None):
            if UPD["state"] == "available":
                threading.Thread(target=upd_apply, daemon=True).start()
            elif UPD["state"] == "idle":
                updm["msg"] = "Keresés…"
                updb.config(text="Keresés…")

                def _chk():
                    upd_check()
                    updm["msg"] = "Naprakész ✓" if UPD["state"] == "idle" and not UPD["err"] else ("Nincs kapcsolat a frissítéshez" if UPD["err"] else "")
                    updm["t"] = time.time()
                threading.Thread(target=_chk, daemon=True).start()

        def upd_tick():
            try:
                stt = UPD["state"]
                if stt == "available":
                    updb.config(text="⬇ Új verzió: %s – kattints a frissítéshez" % UPD["latest"], fg="#5fd68a")
                elif stt == "downloading":
                    updb.config(text="Letöltés…", fg=MUT)
                elif stt == "restart":
                    updb.config(text="Újraindul…", fg=MUT)
                else:
                    if updm.get("msg") and time.time() - updm.get("t", 0) > 45:      # a "Naprakész" uzenet ne maradjon ott orokre
                        updm["msg"] = ""
                    lt_ = UPD.get("t")
                    updb.config(text=updm["msg"] or ("Frissítés keresése (utoljára %s)" % time.strftime("%H:%M", time.localtime(lt_)) if lt_ else "Frissítés keresése"), fg=ACC2)
                root.after(1500, upd_tick)
            except Exception:
                pass
        updb.bind("<Button-1>", upd_click)
        root.after(1500, upd_tick)
