                if not S.get("sim_enabled", True):
                    sdot.itemconfig(sov, fill="#6b7f99")
                    siml.configure(text=L("sim_off"))
                elif S.get("sim_conn"):
                    sdot.itemconfig(sov, fill=GREEN)
